/* Generated by scripts/build-gospel-retellings.py. */
const gospelRetellings = [
  {"id": 91000, "title": "The Family Into Which Jesus Came", "subtitle": "God's promise through generations", "text": "Matthew 1:1–17", "chapters": [[39, 1]], "start": 1, "end": 17, "kind": "story", "category": "Matthew", "story": ["Matthew opens with a family record. Beginning with Abraham, he follows the line through David and the kings of Judah, through the exile in Babylon, and on to Joseph, the husband of Mary. He names Tamar, Rahab, Ruth and the wife of Uriah along the way. The record ends with Jesus, who is called Christ."], "lesson": "The exile could seem to mark the end of David's house. Matthew keeps tracing the line beyond it. God's faithfulness can outlast the losses that make his promises seem remote.", "question": "What does Matthew gain by keeping the exile in the family record?"},
  {"id": 91001, "title": "Joseph Takes Mary Home", "subtitle": "Obedience when plans change", "text": "Matthew 1:18–25", "chapters": [[39, 1]], "start": 18, "end": 25, "kind": "story", "category": "Matthew", "story": ["Joseph learned that Mary was expecting a child before they came together. He planned to end the engagement quietly. In a dream an angel told him the child was conceived by the Holy Spirit and that he should name him Jesus, because he would save his people from their sins. Joseph woke and took Mary as his wife. When the child was born, Joseph gave him the name the angel had spoken."], "lesson": "Joseph was prepared to act without making Mary a public example. When God gave him a different course, he acted on what he had heard.", "question": "Which instructions did Joseph carry out, and what do they show about his trust?"},
  {"id": 91002, "title": "The Visitors From the East", "subtitle": "Two responses to a king", "text": "Matthew 2:1–12", "chapters": [[39, 2]], "start": 1, "end": 12, "kind": "story", "category": "Matthew", "story": ["Wise men arrived in Jerusalem asking where the King of the Jews had been born. Herod was troubled. After learning from the religious teachers that Bethlehem was named by the prophet, he sent the visitors there and asked them to report back. The star led them to the child. They bowed before him and opened their treasures. Warned in a dream, they returned by another road."], "lesson": "Herod learned where the Christ would be born and used that knowledge to protect his power. The visitors used what they learned to seek and worship Jesus. Consider where your knowledge of Scripture is taking you.", "question": "What differences do you see between Herod's questions and the visitors' actions?"},
  {"id": 91003, "title": "The Flight to Egypt and the Return", "subtitle": "God's care amid danger and grief", "text": "Matthew 2:13–23", "chapters": [[39, 2]], "start": 13, "end": 23, "kind": "story", "category": "Matthew", "story": ["An angel warned Joseph to take Jesus and Mary to Egypt because Herod meant to destroy the child. They left at night. When the visitors failed to return, Herod ordered the killing of the young boys in Bethlehem and its vicinity. Matthew recalls Rachel weeping for her children.", "After Herod died, Joseph received word to return. Finding that Archelaus ruled Judea, and warned again in a dream, he settled the family in Nazareth in Galilee."], "lesson": "Matthew records both the child's deliverance and the grief of the bereaved families. God's work in history gives room for lament as well as gratitude.", "question": "Why does Matthew include the cries of the grieving families in the account of Jesus' escape?"},
  {"id": 91004, "title": "A Voice in the Wilderness", "subtitle": "Repentance that bears fruit", "text": "Matthew 3:1–12", "chapters": [[39, 3]], "start": 1, "end": 12, "kind": "story", "category": "Matthew", "story": ["John preached in the wilderness of Judea. People came from Jerusalem and the surrounding country, confessed their sins and were baptised in the Jordan. When Pharisees and Sadducees came, John warned them that descent from Abraham could not stand in place of the fruit of repentance. He told the crowd that someone mightier was coming, one who would baptise with the Holy Spirit and fire."], "lesson": "John's warning reaches people who rely on their religious ancestry. Repentance becomes visible in the life that follows confession.", "question": "What would count as fruit of repentance in a situation you are facing?"},
  {"id": 91005, "title": "Jesus Comes to the Jordan", "subtitle": "The Father's beloved Son", "text": "Matthew 3:13–17", "chapters": [[39, 3]], "start": 13, "end": 17, "kind": "story", "category": "Matthew", "story": ["Jesus came from Galilee to be baptised by John. John hesitated, saying he needed baptism from Jesus. Jesus answered that it was fitting for them to fulfil all righteousness, and John consented. As Jesus came up from the water, the heavens opened. The Spirit of God descended like a dove, and a voice from heaven declared him the beloved Son in whom the Father was pleased."], "lesson": "Jesus willingly took the course that fulfilled righteousness. The Father's declaration identifies the one whose life and teaching Matthew now follows.", "question": "What does the Father's declaration tell you about the person John baptised?"},
  {"id": 91006, "title": "The Test in the Wilderness", "subtitle": "Trusting God under pressure", "text": "Matthew 4:1–11", "chapters": [[39, 4]], "start": 1, "end": 11, "kind": "story", "category": "Matthew", "story": ["After forty days of fasting, Jesus was hungry. The tempter urged him to turn stones into bread. Jesus answered from Scripture. At the temple the tempter quoted Scripture to urge him to throw himself down. Jesus answered that God must not be put to the test. When offered the kingdoms of the world in exchange for worship, Jesus insisted that worship and service belong to God. The devil left, and angels came and ministered to him."], "lesson": "Each offer invited Jesus to take something by abandoning obedience. His answers show that a verse must be read in keeping with what God has commanded.", "question": "How does Jesus' second reply help you recognise a misuse of Scripture?"},
  {"id": 91007, "title": "The First Followers by the Lake", "subtitle": "The call to follow Jesus", "text": "Matthew 4:12–25", "chapters": [[39, 4]], "start": 12, "end": 25, "kind": "story", "category": "Matthew", "story": ["After John was imprisoned, Jesus moved to Capernaum and began preaching repentance because the kingdom of heaven was near. By the lake he called Simon Peter and Andrew away from their nets, promising to make them fishers of people. James and John left their boat and father when he called them. Jesus went through Galilee, teaching, preaching and healing. Crowds followed from far beyond the lake."], "lesson": "The fishermen's response had an immediate cost. Jesus gave them a new purpose whose full meaning they would learn by accompanying him.", "question": "What did the four men leave, and what did Jesus say he would make of them?"},
  {"id": 91008, "title": "The People Jesus Calls Blessed", "subtitle": "A visible life of faith", "text": "Matthew 5:1–16", "chapters": [[39, 5]], "start": 1, "end": 16, "kind": "story", "category": "Matthew", "story": ["Jesus sat on the mountain and taught his disciples. He called the poor in spirit, those who mourn, the meek and those who hunger for righteousness blessed. He spoke of mercy, purity of heart, peacemaking and suffering for righteousness. He then described his followers as salt and light. Their good works were to be visible in such a way that others would glorify their Father."], "lesson": "The blessings correct the way we measure a good life. The light Jesus describes draws attention to the Father through the conduct of his people.", "question": "Which of the blessings would change the way you judge a difficult situation?"},
  {"id": 91009, "title": "Before You Bring Your Gift", "subtitle": "Reconciliation and the heart", "text": "Matthew 5:17–26", "chapters": [[39, 5]], "start": 17, "end": 26, "kind": "story", "category": "Matthew", "story": ["Jesus said he had come to fulfil the law and the prophets. He warned that righteousness must go deeper than that of the scribes and Pharisees. Turning to the command against murder, he addressed anger and contempt. He pictured a worshipper remembering, at the altar, that a brother had something against him. The worshipper was to go and make peace before returning with the gift. Jesus also urged settling a dispute before reaching court."], "lesson": "Jesus connects worship with how we treat people. A serious attempt to make peace can reveal whether we have taken his words about anger to heart.", "question": "What unfinished matter would Jesus' picture of the worshipper bring to your attention?"},
  {"id": 91010, "title": "Faithfulness in Desire and Speech", "subtitle": "Integrity without loopholes", "text": "Matthew 5:27–37", "chapters": [[39, 5]], "start": 27, "end": 37, "kind": "story", "category": "Matthew", "story": ["Jesus taught that adultery can begin in the heart. His severe images about removing a stumbling eye or hand convey the seriousness of dealing with sin. He spoke of the harm involved in putting away a wife and then turned to oaths. He told his hearers to make their yes and no dependable."], "lesson": "Faithfulness reaches into the desires we entertain and the words others must rely on. Jesus calls for decisive action against habits that make unfaithfulness easier.", "question": "Where would a truthful yes or no be better than a promise dressed up to sound convincing?"},
  {"id": 91011, "title": "When an Enemy Needs Your Prayer", "subtitle": "Love patterned after the Father", "text": "Matthew 5:38–48", "chapters": [[39, 5]], "start": 38, "end": 48, "kind": "story", "category": "Matthew", "story": ["Jesus addressed retaliation by picturing a blow, a lawsuit over clothing and a forced mile. He spoke of generosity towards the one who asks. Then he told his hearers to love their enemies and pray for their persecutors. He pointed to the Father, who gives sunshine and rain to people whose conduct differs greatly."], "lesson": "Jesus calls disciples to act beyond the circle of people who repay kindness. Prayer for an enemy places that person's welfare before God and tests our desire for revenge.", "question": "Whom could you pray for by asking God for a specific good in that person's life?"},
  {"id": 91012, "title": "What the Father Sees in Secret", "subtitle": "Giving, prayer and fasting", "text": "Matthew 6:1–18", "chapters": [[39, 6]], "start": 1, "end": 18, "kind": "story", "category": "Matthew", "story": ["Jesus pictured people drawing attention to their giving, prayers and fasting. He directed his disciples to practise these things before the Father. He taught them to pray for God's name, kingdom and will, then for daily bread, forgiveness and deliverance. He pressed the matter of forgiveness and told his disciples to carry on normally when fasting."], "lesson": "The prayer Jesus gave orders our desires around the Father before naming everyday needs. A private practice of mercy or prayer can expose how much we depend on being noticed.", "question": "How might the order of the Lord's Prayer change what you ask for today?"},
  {"id": 91013, "title": "Treasure and Tomorrow", "subtitle": "Trusting the Father for daily needs", "text": "Matthew 6:19–34", "chapters": [[39, 6]], "start": 19, "end": 34, "kind": "story", "category": "Matthew", "story": ["Jesus spoke of treasure that moths, rust and thieves can take, and treasure kept in heaven. He said the heart follows its treasure and that no one can serve both God and money. He turned his hearers' attention to the birds and the lilies. Their Father knows what they need. They were to seek his kingdom and righteousness and deal with the trouble of the day before them."], "lesson": "Jesus connects anxiety about provision with what has first claim on the heart. Trust allows us to attend to today's duties while placing tomorrow before the Father.", "question": "What would seeking God's kingdom first change about one decision concerning money or time?"},
  {"id": 91014, "title": "The Speck and the Beam", "subtitle": "Honest self-examination and generous prayer", "text": "Matthew 7:1–12", "chapters": [[39, 7]], "start": 1, "end": 12, "kind": "story", "category": "Matthew", "story": ["Jesus pictured someone trying to remove a speck from another person's eye while ignoring a beam in his own. He called for self-examination and for discernment about what is holy. Then he encouraged asking, seeking and knocking, comparing the Father's gifts to a parent's care for a child. He taught his hearers to treat others as they would want to be treated."], "lesson": "Correction should begin with honest attention to our own conduct. The Father's generosity also shapes how we approach the needs of others.", "question": "What would removing the beam first change about a conversation you need to have?"},
  {"id": 91015, "title": "Two Builders in the Storm", "subtitle": "Hearing that becomes obedience", "text": "Matthew 7:13–29", "chapters": [[39, 7]], "start": 13, "end": 29, "kind": "story", "category": "Matthew", "story": ["Jesus described a narrow gate and warned that false prophets could be recognised by their fruit. Some would call him Lord and appeal to remarkable works, yet fail to do his Father's will. He finished with two builders. Both houses faced wind and flood. The house built on rock stood, while the house built on sand fell. The crowds were struck by the authority of his teaching."], "lesson": "The storm exposes a difference that was already present in how the builders chose their foundations. Jesus links a sound foundation to hearing his words and doing them.", "question": "Which instruction from the Sermon on the Mount have you heard often enough to put into practice now?"},
  {"id": 91016, "title": "A Man Reaches Out, a Soldier Asks", "subtitle": "The authority and compassion of Jesus", "text": "Matthew 8:1–17", "chapters": [[39, 8]], "start": 1, "end": 17, "kind": "story", "category": "Matthew", "story": ["A man with leprosy knelt before Jesus and asked whether he was willing to make him clean. Jesus touched him, healed him and sent him to the priest. In Capernaum a centurion asked for help for his suffering servant. Knowing how authority worked, he trusted Jesus to give the word from a distance. Jesus also healed Peter's mother-in-law and many who came that evening."], "lesson": "The man with leprosy appealed to Jesus' willingness. The centurion relied on the authority of his word. Both brought a real need before him.", "question": "What did the centurion understand about authority that shaped his request?"},
  {"id": 91017, "title": "The Cost of Following and the Storm", "subtitle": "Discipleship when safety is uncertain", "text": "Matthew 8:18–27", "chapters": [[39, 8]], "start": 18, "end": 27, "kind": "story", "category": "Matthew", "story": ["As Jesus prepared to cross the lake, a scribe volunteered to follow him. Jesus spoke of having nowhere to lay his head. Another disciple asked to go first and bury his father, and Jesus pressed the urgency of following. During the crossing a storm rose while Jesus slept. The disciples woke him. He rebuked the winds and the sea, and the men wondered who he was."], "lesson": "The call to follow Jesus is given before the storm arrives. In the boat the disciples discover how much more they have to learn about the one they follow.", "question": "How do Jesus' words before the crossing prepare you to read what happened on the lake?"},
  {"id": 91018, "title": "Two Men Among the Tombs", "subtitle": "When deliverance unsettles a town", "text": "Matthew 8:28–34", "chapters": [[39, 8]], "start": 28, "end": 34, "kind": "story", "category": "Matthew", "story": ["On the other shore, two fierce men came from the tombs. The demons recognised Jesus and begged to enter a herd of pigs if he drove them out. At his command they went into the herd, which rushed into the water and drowned. The herdsmen reported what had happened. The town came out and begged Jesus to leave its district."], "lesson": "A community can witness a powerful act and still want distance from Jesus. The town's response invites us to examine what we are anxious to protect when his authority disturbs familiar arrangements.", "question": "What happened to the two men, and what did the townspeople ask Jesus to do?"},
  {"id": 91019, "title": "Forgiveness, Healing and a Place at the Table", "subtitle": "Mercy for those who need it", "text": "Matthew 9:1–13", "chapters": [[39, 9]], "start": 1, "end": 13, "kind": "story", "category": "Matthew", "story": ["When people brought a paralysed man to Jesus, he first spoke forgiveness. Some scribes accused him inwardly of blasphemy. Jesus told the man to rise and go home, making his authority to forgive visible through the healing. He then called Matthew from the tax booth. When Pharisees questioned his eating with tax collectors and sinners, Jesus answered with the image of a physician who comes for the sick."], "lesson": "Forgiveness addresses a need the people bringing the man may have overlooked. At Matthew's table Jesus shows why the company of sinners fits his mission of mercy.", "question": "How do Jesus' words to the paralysed man help explain why he ate at Matthew's table?"},
  {"id": 91020, "title": "A Question About Fasting", "subtitle": "Recognising the time and the occasion", "text": "Matthew 9:14–17", "chapters": [[39, 9]], "start": 14, "end": 17, "kind": "story", "category": "Matthew", "story": ["John's disciples asked why they and the Pharisees fasted while Jesus' disciples did not. Jesus compared his presence to a bridegroom at a wedding. A time for fasting would come when the bridegroom was taken away. He then spoke of a new patch that pulls on old cloth and new wine that bursts old skins."], "lesson": "Jesus explains a religious practice in light of his presence and the occasion. The question encourages us to consider whether our habits express a living response to him.", "question": "How does the bridegroom image explain why the disciples' conduct differed?"},
  {"id": 91021, "title": "Interrupted on the Way to a Child", "subtitle": "Faith when hope seems gone", "text": "Matthew 9:18–26", "chapters": [[39, 9]], "start": 18, "end": 26, "kind": "story", "category": "Matthew", "story": ["A ruler came to Jesus because his daughter had died. As Jesus went with him, a woman who had been bleeding for twelve years touched the edge of his garment. Jesus turned, addressed her as daughter and told her that her faith had made her well. At the ruler's house people laughed when Jesus spoke of the girl as sleeping. He took her hand and she rose."], "lesson": "Jesus had time to address the woman personally even on the way to the ruler's house. The account gives attention to two sufferers whom others might have passed over or given up for dead.", "question": "What do Jesus' words to the woman tell you about the way he received her?"},
  {"id": 91022, "title": "Opening Eyes and Seeing the Harvest", "subtitle": "Compassion that asks for workers", "text": "Matthew 9:27–38", "chapters": [[39, 9]], "start": 27, "end": 38, "kind": "story", "category": "Matthew", "story": ["Two blind men followed Jesus, calling for mercy. Inside the house he asked whether they believed he could heal them. He touched their eyes and their sight returned. A man unable to speak was then delivered, drawing wonder from the crowds and hostility from the Pharisees. As Jesus continued through the towns, he saw crowds like sheep without a shepherd. He told his disciples to ask the Lord of the harvest for workers."], "lesson": "Jesus sees more than a crowd. His compassion notices its condition and gives the disciples something specific to pray for.", "question": "Who in your community comes to mind when you read about sheep without a shepherd?"},
  {"id": 91023, "title": "The Twelve Are Sent Out", "subtitle": "Giving freely what you have received", "text": "Matthew 10:1–15", "chapters": [[39, 10]], "start": 1, "end": 15, "kind": "story", "category": "Matthew", "story": ["Jesus chose twelve disciples and gave them authority to heal and cast out unclean spirits. He sent them first to the lost sheep of Israel with the message that the kingdom was near. They were to give freely, travel without collecting supplies and accept hospitality where it was offered. When a house or town refused them, they were to leave and shake the dust from their feet."], "lesson": "Their authority was a gift and their service was to bear the same character. The instructions join generosity with dependence on God and on the hospitality of others.", "question": "How would receiving freely affect the way the disciples treated people who could give them nothing?"},
  {"id": 91024, "title": "Speaking When Opposition Comes", "subtitle": "Courage under the Father's care", "text": "Matthew 10:16–33", "chapters": [[39, 10]], "start": 16, "end": 33, "kind": "story", "category": "Matthew", "story": ["Jesus warned his messengers that they would face councils, rulers and opposition even from relatives. They were to be wise and innocent. When brought before authorities, they could trust the Spirit of their Father for what they should say. Jesus directed them away from fear of people and pointed to the Father's care for sparrows. He called them to acknowledge him openly."], "lesson": "Jesus prepares his followers for costly witness and assures them of the Father's knowledge of each one. His teaching gives courage a firmer basis than the hope that people will approve.", "question": "What does the sparrow illustration contribute to Jesus' instructions about public witness?"},
  {"id": 91025, "title": "A Cup of Cold Water", "subtitle": "Allegiance and welcome", "text": "Matthew 10:34–42", "chapters": [[39, 10]], "start": 34, "end": 42, "kind": "story", "category": "Matthew", "story": ["Jesus warned that allegiance to him could divide households. He spoke of taking up a cross and of losing one's life for his sake. He then turned to the people who would receive his messengers. Receiving them meant receiving him and the one who sent him. Even a cup of cold water given to a little one because the person was a disciple mattered."], "lesson": "The passage places demanding loyalty and ordinary hospitality in the same mission. Help offered quietly to a disciple can express real allegiance to Jesus.", "question": "What kind of welcome is within your reach even if you have little to give?"},
  {"id": 91026, "title": "John Sends a Question From Prison", "subtitle": "Taking uncertainty to Jesus", "text": "Matthew 11:1–19", "chapters": [[39, 11]], "start": 1, "end": 19, "kind": "story", "category": "Matthew", "story": ["From prison John sent disciples to ask whether Jesus was the one who was to come. Jesus pointed to what they could hear and see: healings, restored life and good news preached to the poor. After they left, he spoke of John's place as the messenger preparing the way. He compared the generation to children who refused to respond to either a tune of celebration or a lament."], "lesson": "John's question went directly to Jesus. Jesus answered by directing attention to his works, while exposing the habit of finding an excuse to reject every messenger.", "question": "What evidence did Jesus tell John's disciples to carry back to him?"},
  {"id": 91027, "title": "An Invitation to the Weary", "subtitle": "Repentance and rest", "text": "Matthew 11:20–30", "chapters": [[39, 11]], "start": 20, "end": 30, "kind": "story", "category": "Matthew", "story": ["Jesus rebuked towns that had seen many mighty works without repenting. Then he thanked the Father, who had revealed what was hidden from the wise to little children. He said that knowledge of the Father comes through the Son. He invited those who labour under heavy burdens to come to him, take his yoke and learn from his gentleness."], "lesson": "The invitation to rest comes from the same Jesus who calls the towns to repent. Rest is found in coming under the teaching of a gentle Lord.", "question": "What does Jesus ask weary people to do after they come to him?"},
  {"id": 91028, "title": "Two Sabbath Disputes", "subtitle": "Mercy and doing good", "text": "Matthew 12:1–14", "chapters": [[39, 12]], "start": 1, "end": 14, "kind": "story", "category": "Matthew", "story": ["The disciples picked grain when they were hungry on the Sabbath. When Pharisees objected, Jesus recalled David eating the holy bread and the priests serving on the Sabbath. He appealed to God's desire for mercy and declared himself Lord of the Sabbath. In the synagogue he asked whether a person would rescue a sheep from a pit on that day. Then he restored a man's withered hand."], "lesson": "Jesus makes the suffering person visible in a dispute about rules. His questions call us to examine whether our judgements reflect God's mercy.", "question": "How does the example of the sheep challenge the way the critics looked at the man?"},
  {"id": 91029, "title": "A Healing and an Accusation", "subtitle": "Words reveal the heart", "text": "Matthew 12:15–37", "chapters": [[39, 12]], "start": 15, "end": 37, "kind": "story", "category": "Matthew", "story": ["Jesus withdrew from opposition and continued healing. Matthew recalled Isaiah's description of God's gentle servant. When a man who was blind and unable to speak was healed, the crowds wondered whether Jesus was David's son. The Pharisees attributed the work to the ruler of demons. Jesus answered that a divided kingdom could not stand and spoke of God's kingdom arriving through the Spirit. He warned that speech discloses what fills the heart."], "lesson": "The crowd and the Pharisees saw the same healing and spoke about it differently. Jesus warns us to take seriously the heart from which our judgements and accusations come.", "question": "What did the Pharisees say about the healing, and how did Jesus answer their explanation?"},
  {"id": 91030, "title": "A Sign and a Family", "subtitle": "Responding to the light already given", "text": "Matthew 12:38–50", "chapters": [[39, 12]], "start": 38, "end": 50, "kind": "story", "category": "Matthew", "story": ["Some scribes and Pharisees asked for a sign. Jesus answered with Jonah and warned that the people of Nineveh had repented at Jonah's preaching. He remembered the queen who travelled to hear Solomon and described the danger of an empty house into which an unclean spirit returns. When his mother and brothers stood outside, he pointed to the disciples and named doing his Father's will as the mark of his family."], "lesson": "The passage asks what we do with the light we have already received. Jesus describes a close relationship with him in terms of doing his Father's will.", "question": "How does Nineveh's response challenge the people asking for another sign?"},
  {"id": 91031, "title": "The Sower and Four Soils", "subtitle": "How the word takes root", "text": "Matthew 13:1–23", "chapters": [[39, 13]], "start": 1, "end": 23, "kind": "story", "category": "Matthew", "story": ["Jesus taught from a boat while the crowd stood on the shore. He told of seed falling on a path, rocky ground, among thorns and on good soil. Later he explained the story to his disciples. Trouble cut short the response of some hearers. Worries and riches choked the word in others. Those who heard and understood bore fruit, in differing measures."], "lesson": "The seed meets different conditions. Jesus gives us a way to name what can stop the word from bearing fruit after our first interest in it.", "question": "Which obstacle in Jesus' explanation deserves particular attention in your own life?"},
  {"id": 91032, "title": "Wheat, Weeds and Quiet Growth", "subtitle": "Patience while God brings the harvest", "text": "Matthew 13:24–43", "chapters": [[39, 13]], "start": 24, "end": 43, "kind": "story", "category": "Matthew", "story": ["Jesus described a field in which an enemy sowed weeds among wheat. The farmer told his workers to wait until harvest, because pulling up the weeds too early might uproot the wheat. Jesus also compared the kingdom to a mustard seed and leaven, small beginnings with far-reaching effects. In the house he explained the field and placed the final separation at the end of the age."], "lesson": "The farmer's restraint teaches patience with a world in which good and evil are still mingled. The mustard seed and leaven encourage faith when the kingdom's work seems small.", "question": "What work does the farmer reserve for harvest, and what does that teach about judgement?"},
  {"id": 91033, "title": "Hidden Treasure and a Familiar Town", "subtitle": "Recognising what stands before you", "text": "Matthew 13:44–58", "chapters": [[39, 13]], "start": 44, "end": 58, "kind": "story", "category": "Matthew", "story": ["Jesus compared the kingdom to treasure hidden in a field and a pearl worth selling everything to obtain. A net gathering fish led to another picture of final judgement. He compared a trained teacher to a householder bringing out old and new treasures. Back in his hometown, people wondered at his wisdom but took offence because they knew his family. Their unbelief marked the visit."], "lesson": "The people in the parables recognised value and acted decisively. Jesus' neighbours let their familiarity with his family shape how they received him.", "question": "What difference do you see between the buyers in the parables and the people in Jesus' hometown?"},
  {"id": 91034, "title": "The Death of John the Baptist", "subtitle": "Courage when truth is costly", "text": "Matthew 14:1–12", "chapters": [[39, 14]], "start": 1, "end": 12, "kind": "story", "category": "Matthew", "story": ["Herod had imprisoned John for saying that Herod's marriage to his brother's wife was unlawful. At a birthday celebration, Herod promised a reward to the girl whose dancing pleased him. Prompted by her mother, she asked for John's head. Herod was grieved, yet his oath and his guests weighed heavily. He gave the order. John's disciples buried his body and went to tell Jesus."], "lesson": "Herod allowed public embarrassment to outweigh what he knew he was about to do. John's costly witness makes the weakness behind Herod's display of authority plain.", "question": "Which pressures influenced Herod, and where do similar pressures arise in ordinary decisions?"},
  {"id": 91035, "title": "Bread for the Crowd", "subtitle": "Compassion when resources look small", "text": "Matthew 14:13–21", "chapters": [[39, 14]], "start": 13, "end": 21, "kind": "story", "category": "Matthew", "story": ["Jesus withdrew by boat, but the crowds followed on foot. He had compassion and healed their sick. When evening came, the disciples wanted to send the people away to buy food. Jesus told them to feed the crowd. They brought five loaves and two fish. Jesus blessed and broke the food, and the disciples distributed it. All ate, and twelve baskets of pieces were gathered."], "lesson": "The disciples first saw a problem to send elsewhere. Jesus asked them to bring what they had and made them participants in caring for the crowd.", "question": "What changed when the disciples brought their limited food to Jesus?"},
  {"id": 91036, "title": "Peter Steps Out of the Boat", "subtitle": "Calling on Jesus when fear rises", "text": "Matthew 14:22–36", "chapters": [[39, 14]], "start": 22, "end": 36, "kind": "story", "category": "Matthew", "story": ["Jesus sent the disciples across the lake and went up the mountain to pray. As their boat struggled against the wind, he came towards them on the water. Peter stepped out at his word, became afraid and began to sink. Jesus reached out when Peter called. The wind ceased when they entered the boat, and the disciples worshipped him as God's Son. On the far shore, people brought the sick to him."], "lesson": "Peter had enough trust to step out and enough need to cry for help. The account draws our attention to the hand Jesus extended and the confession the disciples made.", "question": "What did Peter do when he began to sink, and what did the others come to say about Jesus?"},
  {"id": 91037, "title": "Clean Hands and an Unclean Heart", "subtitle": "God's command above custom", "text": "Matthew 15:1–20", "chapters": [[39, 15]], "start": 1, "end": 20, "kind": "story", "category": "Matthew", "story": ["Pharisees and scribes asked why the disciples broke the elders' tradition by eating with unwashed hands. Jesus showed how a tradition could be used to avoid the duty of honouring parents. He then taught the crowd that what comes out of the mouth can defile a person. When Peter asked for an explanation, Jesus named the sins that proceed from the heart."], "lesson": "A religious custom becomes harmful when it makes room for neglect of a clear duty. Jesus points to the heart as the place where the deeper problem must be addressed.", "question": "Which duty did Jesus say the tradition could undermine, and how did it happen?"},
  {"id": 91038, "title": "A Persistent Mother and Another Hungry Crowd", "subtitle": "Mercy beyond familiar borders", "text": "Matthew 15:21–39", "chapters": [[39, 15]], "start": 21, "end": 39, "kind": "story", "category": "Matthew", "story": ["In the region of Tyre and Sidon, a Canaanite woman begged Jesus to help her daughter. After silence and a difficult exchange about Israel and the children's bread, she appealed to the crumbs that fall from a table. Jesus praised her faith, and her daughter was healed. Later, beside the lake in Galilee, Jesus healed many and fed another crowd with seven loaves and a few fish."], "lesson": "The woman keeps her request before Jesus and takes hold of the possibility of mercy in his own illustration. His answer gives weight to the faith of someone the disciples wanted sent away.", "question": "How did the woman answer Jesus' illustration, and what did he commend in her?"},
  {"id": 91039, "title": "Reading the Weather and Missing the Moment", "subtitle": "Discernment about teaching", "text": "Matthew 16:1–12", "chapters": [[39, 16]], "start": 1, "end": 12, "kind": "story", "category": "Matthew", "story": ["Pharisees and Sadducees asked Jesus for a sign from heaven. He compared their ability to read the sky with their failure to read the signs of the times. After crossing the lake, his disciples worried that they had forgotten bread. When Jesus warned them about leaven, they thought he meant their supplies. He reminded them of the two feedings, and they understood that he was warning them about teaching."], "lesson": "Concern about immediate provisions can make it harder to hear a warning on another matter. Jesus calls the disciples to remember what they had already seen him do.", "question": "How did the memory of the feedings help the disciples understand what Jesus meant by leaven?"},
  {"id": 91040, "title": "Peter's Confession and Jesus' Rebuke", "subtitle": "The Christ and the way of the cross", "text": "Matthew 16:13–28", "chapters": [[39, 16]], "start": 13, "end": 28, "kind": "story", "category": "Matthew", "story": ["At Caesarea Philippi, Jesus asked who the disciples believed he was. Peter confessed him as the Christ, the Son of the living God. Jesus spoke of building his church and giving Peter the keys of the kingdom. When Jesus began to speak about suffering, death and resurrection, Peter protested and was sharply rebuked. Jesus told any who would follow him to deny themselves and take up their cross."], "lesson": "Peter spoke truly about Jesus' identity and still resisted what Jesus said about his mission. Understanding who Jesus is requires listening when he describes the road he will take.", "question": "What does Peter accept in his confession, and what does he resist a few verses later?"},
  {"id": 91041, "title": "The Voice on the Mountain", "subtitle": "Listening to the beloved Son", "text": "Matthew 17:1–13", "chapters": [[39, 17]], "start": 1, "end": 13, "kind": "story", "category": "Matthew", "story": ["Jesus took Peter, James and John up a mountain. His appearance changed before them, and Moses and Elijah appeared. Peter proposed building shelters for all three. A bright cloud overshadowed them and a voice called Jesus the beloved Son and told them to hear him. The disciples fell in fear. Jesus touched them, and when they looked up they saw him alone. On the descent he spoke of resurrection and of John the Baptist."], "lesson": "Peter had a proposal ready while the scene was still unfolding. The Father's instruction places listening to Jesus first.", "question": "What would it mean to obey the voice from the cloud as you read what follows?"},
  {"id": 91042, "title": "A Suffering Boy and a Tax Question", "subtitle": "Dependence and consideration", "text": "Matthew 17:14–27", "chapters": [[39, 17]], "start": 14, "end": 27, "kind": "story", "category": "Matthew", "story": ["At the foot of the mountain, a father brought his suffering son to Jesus because the disciples had been unable to help. Jesus delivered the boy and later answered their question about why they had failed. He again told them he would be killed and raised. In Capernaum, collectors asked Peter about the temple tax. Jesus explained the sons' freedom and provided the payment to avoid giving offence."], "lesson": "The healing exposes the disciples' need for faith. The tax conversation shows Jesus considering the effect that exercising a freedom would have on others.", "question": "Why did Jesus choose to pay the tax after explaining that the sons were free?"},
  {"id": 91043, "title": "A Child in the Middle", "subtitle": "The Father's concern for little ones", "text": "Matthew 18:1–14", "chapters": [[39, 18]], "start": 1, "end": 14, "kind": "story", "category": "Matthew", "story": ["The disciples asked who was greatest in the kingdom. Jesus placed a child among them and spoke of becoming humble like the child. He warned against causing little ones to stumble and against despising them. He pictured a shepherd going after one sheep that had strayed, and spoke of the Father's will concerning the little ones."], "lesson": "Jesus answers ambition by giving attention to someone the disciples might overlook. The searching shepherd makes the value of one vulnerable person plain.", "question": "Whose welfare does Jesus direct the disciples to consider when they want to discuss rank?"},
  {"id": 91044, "title": "A Private Conversation and an Unpaid Debt", "subtitle": "Seeking restoration and giving forgiveness", "text": "Matthew 18:15–35", "chapters": [[39, 18]], "start": 15, "end": 35, "kind": "story", "category": "Matthew", "story": ["Jesus described how to approach a fellow believer who sins against you, beginning in private, then involving witnesses and the congregation if needed. Peter asked how often he should forgive. Jesus told of a king who cancelled an immense debt. The pardoned servant then seized a man who owed him much less. When the king heard, he called the servant to account."], "lesson": "The first step aims to regain a brother. The parable asks whether a person who has received mercy is passing it on in the way he deals with others.", "question": "How did the first servant's treatment of his fellow servant contradict the mercy he had received?"},
  {"id": 91045, "title": "A Question About Marriage and a Welcome for Children", "subtitle": "Faithfulness and care for families", "text": "Matthew 19:1–15", "chapters": [[39, 19]], "start": 1, "end": 15, "kind": "story", "category": "Matthew", "story": ["The Pharisees tested Jesus with a question about divorce. He directed them to God's purpose in creation and said Moses had allowed divorce because of hardness of heart. When the disciples asked about the demands of marriage, Jesus recognised that some would remain unmarried for the kingdom. Then people brought children to him. The disciples tried to stop them, but Jesus welcomed them and laid his hands on them."], "lesson": "Jesus brings God's purpose and human hardness of heart into the discussion of marriage. His welcome of children reminds disciples to make room for those who depend on their care.", "question": "What does Jesus give attention to that the disciples were ready to dismiss?"},
  {"id": 91046, "title": "The Man Who Went Away Sad", "subtitle": "When possessions hold the heart", "text": "Matthew 19:16–30", "chapters": [[39, 19]], "start": 16, "end": 30, "kind": "story", "category": "Matthew", "story": ["A young man asked what he must do to have eternal life. Jesus named commandments, and the man said he had kept them. When Jesus told him to sell what he had, give to the poor and follow him, he went away sad because he had many possessions. The disciples were astonished at Jesus' warning about riches. He spoke of what God can do and of what those who leave things for his sake will receive."], "lesson": "The man's sorrow reveals how a possession can become something we cannot imagine surrendering. Jesus turns the disciples from confidence in human ability to dependence on God.", "question": "Where does the man's response change, and what does that change reveal?"},
  {"id": 91047, "title": "The Workers Hired at the Last Hour", "subtitle": "Generosity and comparison", "text": "Matthew 20:1–16", "chapters": [[39, 20]], "start": 1, "end": 16, "kind": "story", "category": "Matthew", "story": ["A landowner hired workers at several times of the day. At evening, those hired last received the same amount as the men who had worked through the heat. The first workers complained. The owner reminded them that he had paid what they agreed and asked why they resented his generosity to the others."], "lesson": "Comparison turned an agreed wage into a grievance. The owner's question invites us to welcome generosity even when someone else receives its benefit.", "question": "What had the first workers been promised, and what made them feel wronged?"},
  {"id": 91048, "title": "A Request for Places and a Cry for Mercy", "subtitle": "Greatness takes the form of service", "text": "Matthew 20:17–34", "chapters": [[39, 20]], "start": 17, "end": 34, "kind": "story", "category": "Matthew", "story": ["On the road to Jerusalem, Jesus told the Twelve again that he would suffer, die and rise. The mother of James and John asked him for places of honour for her sons. Jesus spoke of a cup they would have to drink and taught that greatness among his disciples meant service. Leaving Jericho, he stopped for two blind men whom the crowd was trying to silence. He touched their eyes, and they followed him."], "lesson": "The disciples' dispute about rank is followed by Jesus attending to people a crowd wanted silenced. His conduct shows the kind of greatness he had just described.", "question": "How does Jesus' response to the two men illustrate his teaching about service?"},
  {"id": 91049, "title": "The King Arrives on a Donkey", "subtitle": "Recognising the purpose of worship", "text": "Matthew 21:1–17", "chapters": [[39, 21]], "start": 1, "end": 17, "kind": "story", "category": "Matthew", "story": ["Jesus sent two disciples to fetch a donkey and her colt as he approached Jerusalem. The crowds spread garments and branches on the road and cried Hosanna. In the temple Jesus drove out buyers and sellers and spoke of a house of prayer. The blind and lame came and were healed. When leaders objected to children praising him there, he answered them from Scripture."], "lesson": "The entry and the temple visit reveal what matters to this king. He defends the purpose of prayer and receives people who come to him in need.", "question": "What actions and voices does Matthew bring together in the temple after Jesus enters Jerusalem?"},
  {"id": 91050, "title": "The Fig Tree and Two Sons", "subtitle": "Fruit in conduct", "text": "Matthew 21:18–32", "chapters": [[39, 21]], "start": 18, "end": 32, "kind": "story", "category": "Matthew", "story": ["Jesus found a fig tree with leaves and no fruit, and it withered at his word. He spoke to his disciples about faith and prayer. When the leaders asked who gave him authority, he asked them about John's baptism. They weighed how either answer would affect them and declined to say. He then told of a son who refused to work and later went, and another who agreed but stayed away."], "lesson": "The leaders' calculation stands beside a parable that makes obedience concrete. A sincere change of mind can be seen in what a person goes on to do.", "question": "Which son did his father's will, and how does Jesus apply the answer to John's ministry?"},
  {"id": 91051, "title": "The Tenants and the Son", "subtitle": "Answering to the owner", "text": "Matthew 21:33–46", "chapters": [[39, 21]], "start": 33, "end": 46, "kind": "story", "category": "Matthew", "story": ["Jesus described a man who planted a vineyard, leased it and sent servants to collect the fruit. The tenants beat and killed his messengers. When he sent his son, they killed him in the hope of taking the inheritance. Jesus asked what the owner would do and quoted the Scripture about the rejected stone becoming the cornerstone. The leaders understood that the parables spoke about them."], "lesson": "The tenants treated something entrusted to them as their possession. The story presses anyone entrusted with responsibility to consider what fruit belongs to God.", "question": "What do the tenants' responses to the servants and the son reveal about how they viewed the vineyard?"},
  {"id": 91052, "title": "The Wedding Feast", "subtitle": "Taking the invitation seriously", "text": "Matthew 22:1–14", "chapters": [[39, 22]], "start": 1, "end": 14, "kind": "story", "category": "Matthew", "story": ["Jesus told of a king who prepared a wedding for his son. The invited guests refused to come, and some mistreated and killed his servants. The king sent others to bring people in from the roads, and the hall filled. He then questioned a guest who came without wedding clothing. The guest had no answer."], "lesson": "The invitation reaches widely, even beyond the doors first visited. The king's inspection keeps the hearer from treating an invitation as a reason for indifference.", "question": "What different responses to the king do you find in those invited and in the guest questioned inside?"},
  {"id": 91053, "title": "A Coin and a Question About Resurrection", "subtitle": "God's claim and God's power", "text": "Matthew 22:15–33", "chapters": [[39, 22]], "start": 15, "end": 33, "kind": "story", "category": "Matthew", "story": ["People trying to trap Jesus asked whether paying tax to Caesar was lawful. Jesus asked for a coin and had them identify its image and inscription before telling them to give Caesar and God what belonged to each. The Sadducees then posed a case about a woman married successively to seven brothers. Jesus challenged their understanding of resurrection and appealed to God's words about Abraham, Isaac and Jacob."], "lesson": "Each question tried to confine the answer to its questioner's assumptions. Jesus answered by directing attention to God's claim on people and his power over death.", "question": "Why did Jesus ask about the coin's image before replying to the question about tax?"},
  {"id": 91054, "title": "The Greatest Commandments and David's Lord", "subtitle": "Love at the centre of obedience", "text": "Matthew 22:34–46", "chapters": [[39, 22]], "start": 34, "end": 46, "kind": "story", "category": "Matthew", "story": ["A lawyer asked Jesus which commandment was greatest. Jesus spoke of loving God with heart, soul and mind and loving one's neighbour as oneself. He said the law and the prophets hung on these two. Jesus then asked the Pharisees about the Christ. They called him David's son, and Jesus asked why David also called him Lord."], "lesson": "Love for God and neighbour holds the commands together. Jesus' own question invites the hearers to give closer attention to the identity of the one giving that answer.", "question": "How would the two commands guide you through a decision where your duty to a neighbour is easy to overlook?"},
  {"id": 91055, "title": "The Seats of Honour", "subtitle": "Serving without seeking rank", "text": "Matthew 23:1–12", "chapters": [[39, 23]], "start": 1, "end": 12, "kind": "story", "category": "Matthew", "story": ["Jesus addressed the crowds and disciples about scribes and Pharisees who sat in Moses' seat. He warned against following their example when they failed to practise what they taught. He described heavy burdens laid on others and an appetite for public recognition. Among his hearers, the greatest was to become a servant."], "lesson": "Teaching puts an obligation on the one who teaches. Jesus directs attention to quiet service when titles and public honour begin to matter more.", "question": "Where might a person make a duty heavier for others while declining to help with it?"},
  {"id": 91056, "title": "The Cup, the Tomb and the City", "subtitle": "Justice, mercy and faithfulness", "text": "Matthew 23:13–39", "chapters": [[39, 23]], "start": 13, "end": 39, "kind": "story", "category": "Matthew", "story": ["Jesus pronounced warnings against leaders who shut the kingdom against others and attended to small religious details while neglecting weightier matters. He pictured cups clean outside and tombs that looked beautiful while concealing death. He spoke of prophets who had been killed. Then he lamented over Jerusalem and described his longing to gather its children as a hen gathers her brood."], "lesson": "Outward care can coexist with a neglected inner life. Jesus names justice, mercy and faithfulness plainly, and his lament shows grief over the people he rebukes.", "question": "Which weightier matter did Jesus name that calls for greater attention in your conduct?"},
  {"id": 91057, "title": "The Stones and the Warnings", "subtitle": "Steadiness in troubled times", "text": "Matthew 24:1–28", "chapters": [[39, 24]], "start": 1, "end": 28, "kind": "story", "category": "Matthew", "story": ["As the disciples drew Jesus' attention to the temple buildings, he told them the stones would be thrown down. On the Mount of Olives they asked when these things would happen. Jesus warned of false claims, unrest, persecution, betrayal and cold love. He spoke of the gospel being proclaimed, of danger that would require swift flight and of false reports that the Christ had appeared in a hidden place."], "lesson": "Jesus prepares the disciples for pressure and deception. His warnings direct them to endure and keep their love alive when fear makes dramatic claims easy to believe.", "question": "Which dangers in the passage arise within people themselves, as well as around them?"},
  {"id": 91058, "title": "The Unannounced Hour", "subtitle": "Readiness in ordinary responsibilities", "text": "Matthew 24:29–51", "chapters": [[39, 24]], "start": 29, "end": 51, "kind": "story", "category": "Matthew", "story": ["Jesus described the coming of the Son of Man and used the fig tree to illustrate recognising a season. He said the day and hour were unknown and recalled ordinary life continuing before the flood in Noah's day. He pictured a householder who would stay awake if he knew when a thief was coming. A faithful servant keeps feeding the household while his master is away."], "lesson": "Jesus gives readiness an ordinary shape by describing work that a faithful servant does while waiting. Uncertainty about the hour gives present duties greater weight.", "question": "What is the faithful servant doing when the master returns?"},
  {"id": 91059, "title": "The Lamps at Midnight", "subtitle": "Preparing before the call comes", "text": "Matthew 25:1–13", "chapters": [[39, 25]], "start": 1, "end": 13, "kind": "story", "category": "Matthew", "story": ["Ten young women took lamps to meet a bridegroom. Five brought extra oil and five did not. While the bridegroom was delayed, they all slept. A cry at midnight woke them. Those short of oil went to buy it. The others entered the wedding with the bridegroom, and the door was shut before the late arrivals returned."], "lesson": "The delay exposed a difference in preparation. Jesus' call to watch asks hearers to take responsibility while there is still time to act.", "question": "What did the delay reveal that was already true when the women set out?"},
  {"id": 91060, "title": "The Servants and the Entrusted Money", "subtitle": "Faithfulness with what is in your hands", "text": "Matthew 25:14–30", "chapters": [[39, 25]], "start": 14, "end": 30, "kind": "story", "category": "Matthew", "story": ["A man going away entrusted different sums to three servants according to their ability. Two put the money to work and doubled what they had received. The third hid his share in the ground. On returning, the master commended the first two with the same words. The third explained his fear and returned only what he had buried."], "lesson": "The first two received unequal amounts and the same commendation. The parable turns attention to faithful use of opportunity and exposes the inactivity that fear can excuse.", "question": "What opportunity or responsibility are you tempted to bury because the result is uncertain?"},
  {"id": 91061, "title": "The King Remembers the Least", "subtitle": "Mercy in concrete acts", "text": "Matthew 25:31–46", "chapters": [[39, 25]], "start": 31, "end": 46, "kind": "story", "category": "Matthew", "story": ["Jesus described the Son of Man gathering the nations and separating them as a shepherd separates sheep from goats. The king recalled being fed, welcomed, clothed and visited. Those who had helped asked when they had seen him in need. He told them that what they had done to the least of his brothers they had done to him. He also addressed those who had passed by the same needs."], "lesson": "The judgement brings ordinary acts of care into view. Jesus gives weight to needs that can be overlooked because the person in front of us seems unimportant.", "question": "Which act of care named by the king could you offer to someone this week?"},
  {"id": 91062, "title": "An Anointing in Bethany and a Bargain", "subtitle": "Two ways of valuing Jesus", "text": "Matthew 26:1–16", "chapters": [[39, 26]], "start": 1, "end": 16, "kind": "story", "category": "Matthew", "story": ["As leaders plotted to seize Jesus, he ate at the house of Simon the leper in Bethany. A woman poured costly ointment on his head. The disciples protested about the expense. Jesus defended her and connected her act with his burial. Then Judas went to the chief priests, who agreed to give him thirty pieces of silver for betraying Jesus."], "lesson": "Matthew places a costly gift alongside a price accepted for betrayal. The two scenes ask what our choices reveal about the value we give Jesus.", "question": "How does reading the bargain immediately after the anointing sharpen your understanding of both events?"},
  {"id": 91063, "title": "The Passover Table and Peter's Promise", "subtitle": "The covenant and human weakness", "text": "Matthew 26:17–35", "chapters": [[39, 26]], "start": 17, "end": 35, "kind": "story", "category": "Matthew", "story": ["At the Passover meal Jesus told the disciples that one of them would betray him. Each began to ask whether he was the one. Jesus took bread and the cup, spoke of his body and blood and connected the cup with forgiveness. After they sang and went out, he warned that they would fall away. Peter insisted that he would remain faithful even if it cost his life."], "lesson": "Jesus gives the cup in a room where betrayal and weakness are already present. Peter's promise invites us to pray for the faithfulness we are quick to claim.", "question": "What does the passage reveal about Jesus' purpose and Peter's confidence in himself?"},
  {"id": 91064, "title": "Prayer and Arrest in Gethsemane", "subtitle": "Obedience in anguish", "text": "Matthew 26:36–56", "chapters": [[39, 26]], "start": 36, "end": 56, "kind": "story", "category": "Matthew", "story": ["Jesus took Peter and the sons of Zebedee farther into Gethsemane and asked them to watch. He prayed that the cup might pass, yielding to his Father's will. He found them sleeping and urged them to pray against temptation. Judas arrived with a crowd and identified him by a kiss. Jesus stopped the use of the sword, spoke of the Scriptures being fulfilled, and the disciples fled."], "lesson": "Jesus brings his distress before the Father and yields to him. The disciples' sleep gives urgency to his instruction to watch and pray before the trial reaches them.", "question": "What does Jesus pray for himself, and what does he urge the disciples to pray about?"},
  {"id": 91065, "title": "Inside the Hearing and Outside by the Fire", "subtitle": "Truth under pressure", "text": "Matthew 26:57–75", "chapters": [[39, 26]], "start": 57, "end": 75, "kind": "story", "category": "Matthew", "story": ["Jesus was brought before Caiaphas, where witnesses were sought against him. When the high priest pressed him about being the Christ, Jesus answered and spoke of the Son of Man. The council condemned him and he was mocked. In the courtyard, Peter denied three times that he was with Jesus. When the cock crowed, he remembered Jesus' warning and went out weeping."], "lesson": "Matthew places Jesus' answer alongside Peter's denials. Peter's tears begin with remembering the word he had dismissed earlier that night.", "question": "What brought Peter to recognise what he had done?"},
  {"id": 91066, "title": "Silver Returned and a Prisoner Released", "subtitle": "Responsibility under pressure", "text": "Matthew 27:1–26", "chapters": [[39, 27]], "start": 1, "end": 26, "kind": "story", "category": "Matthew", "story": ["When Judas saw that Jesus was condemned, he returned the silver and confessed that he had betrayed innocent blood. The priests refused responsibility, and Judas went away and took his own life. They used the money to buy a field. Before Pilate, Jesus faced accusations. The crowd chose the release of Barabbas. Pilate washed his hands before them, then handed Jesus over to be crucified."], "lesson": "The priests' reply to Judas and Pilate's gesture both attempt to put responsibility elsewhere. The sequence invites us to face what our decisions actually set in motion.", "question": "What does Pilate do after washing his hands, and why does the order of those actions matter?"},
  {"id": 91067, "title": "The Mocked King on the Cross", "subtitle": "Faithfulness through humiliation", "text": "Matthew 27:27–44", "chapters": [[39, 27]], "start": 27, "end": 44, "kind": "story", "category": "Matthew", "story": ["The soldiers dressed Jesus in a scarlet robe, crowned him with thorns and mocked him. On the way out Simon of Cyrene was compelled to carry the cross. At Golgotha Jesus was crucified, his clothing was divided and the written charge named him King of the Jews. Passers-by and leaders mocked him, challenging him to come down and save himself."], "lesson": "The mockers treated escape as the proof of who Jesus was. Matthew has already shown Jesus choosing the path that would bring him to this place.", "question": "How do the mockers' challenges sound in light of what Jesus prayed in Gethsemane?"},
  {"id": 91068, "title": "The Torn Curtain and the Sealed Tomb", "subtitle": "Witness in the hour of grief", "text": "Matthew 27:45–66", "chapters": [[39, 27]], "start": 45, "end": 66, "kind": "story", "category": "Matthew", "story": ["Darkness fell. Jesus cried out and then died. The temple curtain tore, the earth shook and Matthew describes tombs opening. The centurion and those with him were afraid and spoke of Jesus as God's Son. Women who had followed from Galilee watched. Joseph of Arimathea laid the body in his own tomb, with women watching nearby. Leaders asked Pilate for a guard and the stone was sealed."], "lesson": "Joseph and the women remain present after public disgrace and death. The passage gives quiet acts of care and witness a place beside events of great public consequence.", "question": "Who remained close enough to witness the burial, and what did Joseph do?"},
  {"id": 91069, "title": "The Women at the Tomb", "subtitle": "Fear, joy and truthful witness", "text": "Matthew 28:1–15", "chapters": [[39, 28]], "start": 1, "end": 15, "kind": "story", "category": "Matthew", "story": ["At dawn two women went to see the tomb. An earthquake came, an angel rolled back the stone and the guards trembled. The angel announced that Jesus had risen and sent the women to tell the disciples. On the way Jesus met them, and they took hold of his feet and worshipped. Some guards reported what had happened and were paid to spread a different account."], "lesson": "The women carried their message with fear and great joy. The payment to the guards shows the pressure that can surround the telling of what one has witnessed.", "question": "What did the women see and hear before Jesus sent them on their way?"},
  {"id": 91070, "title": "The Last Meeting on the Mountain", "subtitle": "Making disciples with Jesus' presence", "text": "Matthew 28:16–20", "chapters": [[39, 28]], "start": 16, "end": 20, "kind": "story", "category": "Matthew", "story": ["The eleven went to the mountain in Galilee that Jesus had appointed. They worshipped him, and some doubted. Jesus declared that all authority in heaven and earth had been given to him. He sent them to make disciples of all nations, baptising them and teaching them to observe his commands. He promised to be with them to the end of the age."], "lesson": "Jesus joins his authority to a command and a promise. Teaching people to practise what he commanded takes sustained attention, and the work rests on his continuing presence.", "question": "Which parts of Jesus' commission require a relationship that continues after a person first hears the message?"},
  {"id": 91071, "title": "The Road, the River and the Wilderness", "subtitle": "The beginning of the good news", "text": "Mark 1:1–13", "chapters": [[40, 1]], "start": 1, "end": 13, "kind": "story", "category": "Mark", "story": ["Mark begins in the wilderness, where John calls people to repentance and baptises them. John points forward to someone who will baptise with the Holy Spirit. Jesus comes from Nazareth, is baptised and hears the Father's voice. The Spirit immediately drives him into the wilderness, where he is tempted for forty days and angels minister to him."], "lesson": "The Father's declaration precedes the wilderness. A place of testing can come directly after a clear word of assurance.", "question": "What does Mark tell you about Jesus before he records his first public words?"},
  {"id": 91072, "title": "From the Nets to the Doorway", "subtitle": "Authority that reaches ordinary homes", "text": "Mark 1:14–34", "chapters": [[40, 1]], "start": 14, "end": 34, "kind": "story", "category": "Mark", "story": ["After John is put in prison, Jesus announces the kingdom and calls four fishermen. In Capernaum he teaches in the synagogue and commands an unclean spirit to leave a man. Then he goes into Simon and Andrew's home, where Simon's mother-in-law lies ill. He lifts her up, and she begins serving them. By evening many from the town have come to the door."], "lesson": "Mark follows Jesus from public teaching to a sickbed in a home. His authority has a personal reach, and the healed woman answers with service.", "question": "What does Jesus do for Simon's mother-in-law, and what is her first recorded response?"},
  {"id": 91073, "title": "The Place of Prayer and the Man Outside", "subtitle": "Compassion guided by purpose", "text": "Mark 1:35–45", "chapters": [[40, 1]], "start": 35, "end": 45, "kind": "story", "category": "Mark", "story": ["Before daylight Jesus went to a solitary place to pray. Simon and the others found him and said everyone was looking for him. Jesus led them towards other towns to preach. A man with leprosy asked to be made clean. Jesus touched him and sent him to the priest, instructing him to keep quiet. The man told many people, and Jesus could no longer enter a town openly."], "lesson": "The search of the crowd did not settle where Jesus would go. Prayer and the purpose for which he came help us read his decision to move on.", "question": "How did Jesus respond when told that everyone was looking for him?"},
  {"id": 91074, "title": "Through the Roof and Around the Table", "subtitle": "Forgiveness and fellowship", "text": "Mark 2:1–17", "chapters": [[40, 2]], "start": 1, "end": 17, "kind": "story", "category": "Mark", "story": ["A crowd filled the house where Jesus was teaching. Four men carried a paralysed man to the roof, opened it and lowered him. Jesus spoke forgiveness, then healed him openly when scribes questioned his authority. Later Jesus called Levi from the tax booth and ate with people whom the scribes regarded as sinners. He spoke of a physician whose work was with the sick."], "lesson": "The four men make their faith visible through steady trouble on another person's behalf. Jesus brings the man's need of forgiveness into view before he sends him home walking.", "question": "What do the four men recognise about the need to bring their friend to Jesus?"},
  {"id": 91075, "title": "A Wedding and a Walk Through Grain", "subtitle": "Receiving God's gifts in their purpose", "text": "Mark 2:18–28", "chapters": [[40, 2]], "start": 18, "end": 28, "kind": "story", "category": "Mark", "story": ["People asked why Jesus' disciples did not fast as others did. He compared his presence to a bridegroom's time with his guests and used images of cloth and wineskins. On a Sabbath the disciples plucked grain as they passed through a field. Jesus answered an objection by recalling David's need and said that the Sabbath was made for people. He declared the Son of Man Lord of it."], "lesson": "Jesus draws attention to the occasion for a practice and the purpose for which God gave it. Those questions can expose needless severity in our treatment of people.", "question": "How does Jesus use David's need to answer the objection over the grain?"},
  {"id": 91076, "title": "A Hand Restored and Twelve Appointed", "subtitle": "Being with Jesus before being sent", "text": "Mark 3:1–19", "chapters": [[40, 3]], "start": 1, "end": 19, "kind": "story", "category": "Mark", "story": ["In the synagogue Jesus called a man with a withered hand to stand where everyone could see him. He asked whether the Sabbath permitted doing good or harm. Their silence grieved him, and he restored the hand. Opposition grew as crowds gathered. On a mountain Jesus appointed twelve, calling them to be with him and preparing to send them to preach."], "lesson": "Jesus puts a man's need in the centre of the room. When he appoints the Twelve, he makes being with him part of their calling before their public work.", "question": "What two purposes does Mark name when Jesus appoints the Twelve?"},
  {"id": 91077, "title": "Voices Outside the House", "subtitle": "The family that does God's will", "text": "Mark 3:20–35", "chapters": [[40, 3]], "start": 20, "end": 35, "kind": "story", "category": "Mark", "story": ["People close to Jesus sought to take charge of him after hearing what was said about him. Scribes from Jerusalem attributed his authority over demons to their ruler. Jesus answered with a divided house and the image of binding a strong man. When his mother and brothers waited outside, he looked at those sitting around him and called those who do God's will his family."], "lesson": "Outsiders were busy explaining Jesus, while people around him were listening to him. The family he names is marked by a response to God's will.", "question": "How does Jesus' picture of a divided house answer the scribes' charge?"},
  {"id": 91078, "title": "The Seed and the Lamp", "subtitle": "Attending to what you hear", "text": "Mark 4:1–25", "chapters": [[40, 4]], "start": 1, "end": 25, "kind": "story", "category": "Mark", "story": ["Jesus taught the crowd from a boat about seed landing in four kinds of soil. Alone with his followers, he explained how opposition, worries and the desire for riches can cut short the effect of the word. He spoke of a lamp brought to be set on a stand and urged his hearers to take heed to what they heard."], "lesson": "The parable gives us more to examine than our first response to the word. It asks whether we are making room for it to grow after that first hearing.", "question": "What do the thorns represent, and where could they be choking what you have heard?"},
  {"id": 91079, "title": "A Growing Field and a Quiet Sea", "subtitle": "Faith when you cannot control events", "text": "Mark 4:26–41", "chapters": [[40, 4]], "start": 26, "end": 41, "kind": "story", "category": "Mark", "story": ["Jesus described seed growing while a farmer slept and a mustard seed becoming a large plant. That evening the disciples took him across the water. A storm filled the boat while Jesus slept on a cushion. They woke him with a question about whether he cared. He silenced the wind and sea, then asked about their fear and faith. The disciples wondered who he was."], "lesson": "The farmer cannot account for every stage of the growth, and the disciples cannot command the storm. The two scenes ask where trust belongs when events are beyond our control.", "question": "What did the disciples' question assume about Jesus while he was asleep?"},
  {"id": 91080, "title": "The Man Who Wanted to Go With Jesus", "subtitle": "Witness starts at home", "text": "Mark 5:1–20", "chapters": [[40, 5]], "start": 1, "end": 20, "kind": "story", "category": "Mark", "story": ["On the far shore a man who lived among the tombs ran to Jesus. The spirits called themselves Legion. At Jesus' command they left him and entered pigs that rushed into the lake. The villagers found the man sitting clothed and in his right mind and asked Jesus to leave. The man asked to go with him. Jesus instead sent him home to tell what the Lord had done for him."], "lesson": "The restored man received a task close to home. Telling people who knew his former condition gave them a concrete account of mercy.", "question": "What did Jesus ask the man to tell his own people?"},
  {"id": 91081, "title": "Two Daughters in Need", "subtitle": "Jesus receives the hidden sufferer", "text": "Mark 5:21–43", "chapters": [[40, 5]], "start": 21, "end": 43, "kind": "story", "category": "Mark", "story": ["Jairus begged Jesus to come to his dying daughter. On the way a woman who had suffered for twelve years touched Jesus' clothing. He stopped, heard her tell the truth and called her daughter. News then came that Jairus's child had died. Jesus went on, took the girl's hand and told her to rise. Afterwards he gave instructions that she should be fed."], "lesson": "Jesus addresses one sufferer in a crowd and remembers an ordinary need after raising another. Care can include attention to details others consider too small to notice.", "question": "What did Jesus ask people to do for the girl after she rose?"},
  {"id": 91082, "title": "The Hometown and the Roads Beyond", "subtitle": "Witness amid rejection", "text": "Mark 6:1–13", "chapters": [[40, 6]], "start": 1, "end": 13, "kind": "story", "category": "Mark", "story": ["Jesus taught in his hometown, where people took offence at someone whose work and family they knew. He marvelled at their unbelief and continued through the villages. He sent the Twelve in pairs, instructing them to travel lightly, stay where welcomed and leave a testimony where people refused them. They preached repentance and ministered to the sick."], "lesson": "Rejection in a familiar place did not end the work. Jesus trained the Twelve to minister together and to handle refusals without getting stuck in them.", "question": "What did Jesus instruct the Twelve to do when a place would not receive them?"},
  {"id": 91083, "title": "Herod's Banquet and John's Death", "subtitle": "The cost of pleasing an audience", "text": "Mark 6:14–29", "chapters": [[40, 6]], "start": 14, "end": 29, "kind": "story", "category": "Mark", "story": ["When reports of Jesus reached Herod, he remembered John, whom he had beheaded. John had spoken against his marriage. Herod feared John and listened to him, while Herodias wanted him dead. At a banquet her daughter asked for John's head after Herod offered her a reward. Herod was grieved and gave the order because of his oaths and the guests."], "lesson": "Listening to a truthful person can coexist with refusing to act on what he says. Herod's decision shows what can happen when approval in a room matters more than conscience.", "question": "How did Herod's opinion of John differ from what he finally chose to do?"},
  {"id": 91084, "title": "Bread for the Crowd and Jesus on the Water", "subtitle": "Remembering the help already given", "text": "Mark 6:30–56", "chapters": [[40, 6]], "start": 30, "end": 56, "kind": "story", "category": "Mark", "story": ["The apostles returned tired, and Jesus took them aside. The crowd arrived ahead of them. Seeing people like sheep without a shepherd, Jesus taught them and fed them with five loaves and two fish. After praying on the mountain, he came across the water to the disciples. They were terrified, and the wind fell when he joined them. Mark connects their astonishment with their failure to understand the loaves."], "lesson": "A fresh fear can hide the significance of help we have just received. Mark invites readers to hold the feeding and the crossing together as they ask who Jesus is.", "question": "What does Mark say the disciples had failed to understand before the crossing?"},
  {"id": 91085, "title": "The Gift That Excused Neglect", "subtitle": "Looking beneath religious appearances", "text": "Mark 7:1–23", "chapters": [[40, 7]], "start": 1, "end": 23, "kind": "story", "category": "Mark", "story": ["Scribes and Pharisees questioned the disciples' eating customs. Jesus answered by describing how a claim that something was devoted to God could be used to withhold help from parents. He then taught the crowd about what defiles a person. In the house he explained that evil actions and desires come out of the heart."], "lesson": "A religious claim can become a polished excuse for neglecting someone. Jesus makes both the neglected duty and the motives of the heart visible.", "question": "Which command did Jesus say could be set aside through the tradition about gifts?"},
  {"id": 91086, "title": "A Mother's Reply and an Opened Ear", "subtitle": "Mercy in unfamiliar places", "text": "Mark 7:24–37", "chapters": [[40, 7]], "start": 24, "end": 37, "kind": "story", "category": "Mark", "story": ["In the district of Tyre a Gentile woman asked Jesus to deliver her daughter. He spoke of the children's bread, and she answered that dogs beneath the table ate the children's crumbs. Jesus sent her home to find the child delivered. Later people brought him a man who could scarcely hear or speak. Jesus took him aside, looked towards heaven and opened his ears."], "lesson": "Jesus hears the mother's reply and deals personally with the man brought by others. People beyond familiar religious boundaries receive his attention.", "question": "What do you learn from the way Jesus handled the man privately before the healing became widely known?"},
  {"id": 91087, "title": "Another Meal and Sight in Stages", "subtitle": "Learning to see what is before you", "text": "Mark 8:1–26", "chapters": [[40, 8]], "start": 1, "end": 26, "kind": "story", "category": "Mark", "story": ["Jesus fed another hungry crowd, this time with seven loaves and a few fish. Pharisees asked him for a sign, and he sighed deeply. In the boat the disciples worried about bread and missed his warning about leaven. He asked them to recall the baskets left after both meals. At Bethsaida a blind man first saw people like walking trees, then saw clearly after Jesus touched him again."], "lesson": "Mark places questions about seeing beside a healing in stages. Honest attention to what we only partly understand can make room for further instruction.", "question": "What do the disciples remember about the baskets, and what do they still need to understand?"},
  {"id": 91088, "title": "The Confession on the Road", "subtitle": "The identity of Jesus and the cost of following", "text": "Mark 8:27–38", "chapters": [[40, 8]], "start": 27, "end": 38, "kind": "story", "category": "Mark", "story": ["On the road near Caesarea Philippi, Jesus asked the disciples who people said he was. Peter answered the more direct question by saying he was the Christ. When Jesus began teaching about suffering, rejection, death and rising again, Peter rebuked him. Jesus called the crowd to hear what following him meant. He asked what it would profit someone to gain the world and lose his life."], "lesson": "Peter accepts a title and objects to what Jesus says it will involve. Jesus teaches disciples to examine what they are protecting when his way calls for surrender.", "question": "What words of Jesus provoked Peter's objection?"},
  {"id": 91089, "title": "Glory on the Mountain and Need Below", "subtitle": "Prayer when faith is weak", "text": "Mark 9:1–29", "chapters": [[40, 9]], "start": 1, "end": 29, "kind": "story", "category": "Mark", "story": ["Jesus was transfigured before Peter, James and John, and a voice from the cloud told them to hear him. Below, a crowd gathered around the other disciples, who had been unable to help a suffering boy. The boy's father pleaded with Jesus and acknowledged that he needed help with his unbelief. Jesus delivered the boy. Later he spoke to the disciples about prayer."], "lesson": "The father's plea gives words to imperfect faith. He brings his uncertainty to Jesus along with his son's need.", "question": "How does the father's plea hold belief and need together?"},
  {"id": 91090, "title": "The Argument They Kept Quiet", "subtitle": "Welcome, humility and care", "text": "Mark 9:30–50", "chapters": [[40, 9]], "start": 30, "end": 50, "kind": "story", "category": "Mark", "story": ["Jesus again spoke of his death and resurrection. On the road the disciples argued about greatness and fell silent when he asked about it. He set a child among them and spoke of welcoming such a child in his name. When John reported that they had tried to stop someone working in Jesus' name, Jesus told them to let him be. He warned them about causing others to stumble and called them to peace."], "lesson": "The disciples' argument kept their attention on position. Jesus gave them practical matters to consider, including the welcome they offered and the harm they might cause.", "question": "What did Jesus place before the disciples to give their argument a different direction?"},
  {"id": 91091, "title": "Children at the Door and a Man With Wealth", "subtitle": "Receiving the kingdom with open hands", "text": "Mark 10:1–31", "chapters": [[40, 10]], "start": 1, "end": 31, "kind": "story", "category": "Mark", "story": ["Jesus answered a question about divorce by returning to God's purpose for marriage. When children were brought to him, the disciples rebuked those bringing them. Jesus welcomed and blessed the children. A man then asked about eternal life. Jesus looked at him with love and called him to give to the poor and follow. He went away grieved because he had many possessions."], "lesson": "Mark records Jesus' love for the man who walked away. It makes the hard instruction personal and shows that a demand can come from love.", "question": "What does Mark say about the way Jesus looked at the man before giving the instruction?"},
  {"id": 91092, "title": "Two Requests on the Road", "subtitle": "Serving and seeing", "text": "Mark 10:32–52", "chapters": [[40, 10]], "start": 32, "end": 52, "kind": "story", "category": "Mark", "story": ["Jesus walked ahead on the way to Jerusalem and spoke of what awaited him. James and John asked to sit in places of honour. Jesus asked about the cup they would drink and spoke of giving his life as a ransom. Outside Jericho, Bartimaeus called for mercy despite attempts to hush him. Jesus asked what he wanted. Bartimaeus asked to see and followed him along the road."], "lesson": "Jesus asks what people want in both scenes. The answers reveal different desires as he goes towards Jerusalem.", "question": "What do James and John ask for, and what does Bartimaeus ask for when Jesus stops?"},
  {"id": 91093, "title": "Branches, a Temple and a Withered Tree", "subtitle": "The fruit of prayer and forgiveness", "text": "Mark 11:1–26", "chapters": [[40, 11]], "start": 1, "end": 26, "kind": "story", "category": "Mark", "story": ["Jesus entered Jerusalem amid cries of Hosanna. The next day he found a fig tree with leaves and no fruit. In the temple he drove out buyers and sellers and recalled its purpose as a house of prayer for all nations. The disciples later saw that the tree had withered. Jesus taught about faith in prayer and about forgiving when they stood praying."], "lesson": "Mark places the temple visit between the two encounters with the tree. The sequence invites examination of the fruit of worship, including a willingness to forgive.", "question": "Which instruction about forgiveness accompanies Jesus' teaching about faith and prayer?"},
  {"id": 91094, "title": "An Answer Kept Back", "subtitle": "Being honest about authority", "text": "Mark 11:27–33", "chapters": [[40, 11]], "start": 27, "end": 33, "kind": "story", "category": "Mark", "story": ["Chief priests, scribes and elders asked who authorised Jesus' actions. He asked whether John's baptism came from heaven or from people. They discussed the consequences of saying either one. One answer would invite a question about why they had not believed John. The other might anger the crowd. They claimed ignorance, and Jesus declined to answer their demand."], "lesson": "Concern for position governed their discussion. When an honest answer carries a cost, the passage asks us to notice the temptation to retreat into convenient uncertainty.", "question": "What were the leaders considering when they decided how to answer?"},
  {"id": 91095, "title": "The Vineyard, the Coin and the Living God", "subtitle": "Answering to God", "text": "Mark 12:1–27", "chapters": [[40, 12]], "start": 1, "end": 27, "kind": "story", "category": "Mark", "story": ["Jesus told of tenants who beat the owner's servants and killed his beloved son. The leaders recognised the story's direction. Then questioners brought him a coin in a dispute over tax, and he spoke of giving God what belongs to God. The Sadducees posed a puzzle about marriage after resurrection. Jesus answered from the words God spoke at the bush, calling him the God of the living."], "lesson": "The passages move from responsibility for what is entrusted to us towards God's claim and power. Jesus reads each question against what the questioners have missed about God.", "question": "How does the owner's claim in the parable help you consider what belongs to God?"},
  {"id": 91096, "title": "The Listening Scribe and the Widow's Coins", "subtitle": "Wholehearted devotion", "text": "Mark 12:28–44", "chapters": [[40, 12]], "start": 28, "end": 44, "kind": "story", "category": "Mark", "story": ["A scribe asked which command came first. Jesus answered with love for God and neighbour. The scribe replied thoughtfully, and Jesus said he was near the kingdom. Jesus then asked about David's Lord and warned about scribes who sought honour and devoured widows' houses. At the treasury he drew attention to a poor widow who gave two small coins, all she had to live on."], "lesson": "The attentive scribe and the widow each receive an individual response from Jesus. He considers the substance of a person's devotion, which a public display or the amount of a gift may conceal.", "question": "What did Jesus notice about the widow's gift that an observer counting coins could miss?"},
  {"id": 91097, "title": "Across From the Temple", "subtitle": "Discernment under pressure", "text": "Mark 13:1–23", "chapters": [[40, 13]], "start": 1, "end": 23, "kind": "story", "category": "Mark", "story": ["Jesus told a disciple that the temple stones would be thrown down. Across from the temple four disciples asked privately when this would happen. Jesus warned of deceptive claims, wars and persecution. He spoke of the witness his followers would give and the help of the Holy Spirit. He described distress that would require flight and told them in advance to beware of false signs."], "lesson": "Jesus answers the question about timing by preparing his followers for discernment and endurance. His promise concerning the Spirit addresses a real moment of vulnerability.", "question": "What instructions does Jesus give for a time when fear and false claims are widespread?"},
  {"id": 91098, "title": "The Doorkeeper's Watch", "subtitle": "Faithfulness while waiting", "text": "Mark 13:24–37", "chapters": [[40, 13]], "start": 24, "end": 37, "kind": "story", "category": "Mark", "story": ["Jesus described the Son of Man coming in power and glory and gathering his elect. The fig tree's leaves illustrated recognising that a season was near. Jesus then said the day and hour were unknown. He compared the situation to a master leaving his servants their own work and charging the doorkeeper to watch for his return."], "lesson": "Each servant has work while the master is away. Jesus joins expectancy to attention to the duty already assigned.", "question": "What has the master already given each servant to do before he returns?"},
  {"id": 91099, "title": "The Costly Gift and the Shared Cup", "subtitle": "Devotion in a room of weakness", "text": "Mark 14:1–25", "chapters": [[40, 14]], "start": 1, "end": 25, "kind": "story", "category": "Mark", "story": ["At Bethany a woman poured expensive ointment on Jesus. Some reproached her, and he defended her action as preparation for his burial. Judas went to the chief priests. During the Passover meal Jesus spoke of betrayal, and the disciples questioned themselves. He shared bread and a cup and spoke of his body and the blood of the covenant poured out for many."], "lesson": "The anointing is remembered for what the woman did within her reach. At the meal Jesus gives his disciples a way to remember what he is doing for them.", "question": "Why does Jesus link the woman's gift with his burial?"},
  {"id": 91100, "title": "The Sleeping Friends and the Arrest", "subtitle": "Watching and yielding to the Father", "text": "Mark 14:26–52", "chapters": [[40, 14]], "start": 26, "end": 52, "kind": "story", "category": "Mark", "story": ["After leaving the meal Jesus warned that the disciples would scatter, and Peter protested. In Gethsemane Jesus told three of them to watch. He prayed to the Father in distress and yielded to his will. The disciples repeatedly slept. Judas arrived and greeted Jesus with a kiss, the crowd seized him and his followers fled. Mark also records a young man who escaped by leaving his linen cloth behind."], "lesson": "Jesus had warned the disciples about their weakness before the crowd arrived. The passage shows the need to bring that weakness into prayer while there is time.", "question": "What did Jesus warn Peter about the spirit and the flesh when he found him asleep?"},
  {"id": 91101, "title": "Peter Below in the Courtyard", "subtitle": "Remembering the word after failure", "text": "Mark 14:53–72", "chapters": [[40, 14]], "start": 53, "end": 72, "kind": "story", "category": "Mark", "story": ["Witnesses brought charges before the high priest, but their testimony did not agree. Asked whether he was the Christ, Jesus answered and was condemned. Below in the courtyard a servant girl recognised Peter and he denied knowing Jesus. The accusations continued, and Peter denied him again. When the cock crowed a second time, Peter remembered the warning and wept."], "lesson": "Remembering Jesus' words allowed Peter to recognise his failure. A word we once resisted can become the beginning of honest repentance.", "question": "What detail brought Jesus' warning back to Peter's mind?"},
  {"id": 91102, "title": "The Rejected Prisoner and the Mock Crown", "subtitle": "Recognising the power of a crowd", "text": "Mark 15:1–20", "chapters": [[40, 15]], "start": 1, "end": 20, "kind": "story", "category": "Mark", "story": ["The council handed Jesus over to Pilate. Pilate questioned him and marvelled at his silence before further charges. Offered a release, the crowd called for Barabbas and demanded that Jesus be crucified. Pilate yielded to satisfy them. Soldiers dressed Jesus in purple, crowned him with thorns and saluted him in mockery before leading him out."], "lesson": "Mark gives a reason for Pilate's decision: he wanted to satisfy the crowd. His choice asks what happens when a person uses authority chiefly to preserve approval.", "question": "What did Pilate know about the chief priests' motives, and how did he still decide?"},
  {"id": 91103, "title": "The Centurion, the Women and the Tomb", "subtitle": "Witness and courage at the cross", "text": "Mark 15:21–47", "chapters": [[40, 15]], "start": 21, "end": 47, "kind": "story", "category": "Mark", "story": ["Simon of Cyrene was compelled to carry the cross. Jesus was crucified and mocked. Darkness fell, and he cried out before he died. The temple curtain tore. The centurion who stood facing him called him God's Son. Women watched from a distance. Joseph of Arimathea went to Pilate for the body, laid it in a tomb and rolled a stone across the entrance. The women saw where he was laid."], "lesson": "People in different places bear witness to what happened. Joseph's request took courage, while the women attended closely enough to know where to return.", "question": "Which details does Mark give about the people who saw Jesus die or saw where he was buried?"},
  {"id": 91104, "title": "The Stone Already Rolled Away", "subtitle": "Hope spoken to failing disciples", "text": "Mark 16:1–8", "chapters": [[40, 16]], "start": 1, "end": 8, "kind": "story", "category": "Mark", "story": ["After the Sabbath, Mary Magdalene, Mary the mother of James and Salome took spices to the tomb. They wondered who would move the stone. On arriving they saw it had been rolled away. A young man in white told them Jesus had risen and pointed to the place where he had lain. He directed them to tell the disciples and Peter about Galilee. The women went out trembling."], "lesson": "Peter is named when the message is sent to the disciples. Readers who remember his denial can hear the personal care in that small addition.", "question": "What difference does the mention of Peter make after the account of his denial?"},
  {"id": 91105, "title": "The News Carried Outward", "subtitle": "From unbelief to witness", "text": "Mark 16:9–20", "chapters": [[40, 16]], "start": 9, "end": 20, "kind": "story", "category": "Mark", "story": ["In the closing verses printed in the King James Version, Jesus appears first to Mary Magdalene, whose report is disbelieved. Other witnesses also meet disbelief. Jesus appears to the eleven and sends them to preach the gospel. After he is received into heaven, they go out preaching, and the account describes the Lord working with them."], "lesson": "The people commissioned to speak had themselves struggled to believe. Their earlier failure gives context to the patient work of bearing witness to others.", "question": "How do the disciples' first reactions compare with what they do at the close of the passage?"},
  {"id": 91106, "title": "Zechariah Comes Out Silent", "subtitle": "A promise in the years of waiting", "text": "Luke 1:1–25", "chapters": [[41, 1]], "start": 1, "end": 25, "kind": "story", "category": "Luke", "story": ["Luke tells Theophilus that he has set the events in order after tracing them carefully. He begins with Zechariah and Elisabeth, who are old and childless. While Zechariah offers incense, Gabriel tells him that their son John will prepare people for the Lord. Zechariah asks how he can know. He comes out unable to speak. Elisabeth conceives and withdraws for five months."], "lesson": "Luke presents the couple as faithful before their prayer is answered. Elisabeth's years of waiting deserve attention alongside the joy that follows.", "question": "How does Luke describe Zechariah and Elisabeth before Gabriel brings the news?"},
  {"id": 91107, "title": "Mary Goes to See Elisabeth", "subtitle": "Believing God's word in uncertain circumstances", "text": "Luke 1:26–56", "chapters": [[41, 1]], "start": 26, "end": 56, "kind": "story", "category": "Luke", "story": ["Gabriel tells Mary that she will bear Jesus, the Son of the Highest and heir to David's throne. He answers her question with the promise of the Holy Spirit and news of Elisabeth. Mary accepts the word and goes to her relative. Elisabeth's child leaps, and she blesses Mary for believing. Mary praises God for seeing her low estate and remembering his promise to Israel."], "lesson": "Mary's praise places her own experience inside God's mercy to generations. Elisabeth's welcome gives her a place to share what has happened.", "question": "What parts of Mary's song reach beyond her own circumstances?"},
  {"id": 91108, "title": "The Name Written on the Tablet", "subtitle": "Mercy remembered and a way prepared", "text": "Luke 1:57–80", "chapters": [[41, 1]], "start": 57, "end": 80, "kind": "story", "category": "Luke", "story": ["At the child's circumcision, neighbours expect a family name. Elisabeth says he will be called John. Zechariah writes the same name, and his speech returns. He blesses God for remembering his covenant and speaks of the child preparing the Lord's way. His prophecy ends with light for those in darkness and feet guided into peace."], "lesson": "The name marks obedience to what was spoken before the child was born. Zechariah uses his restored speech to bless God and to describe a calling greater than family expectations.", "question": "What does Zechariah say John will do for the people?"},
  {"id": 91109, "title": "The Night the Shepherds Went to Bethlehem", "subtitle": "Good news carried by ordinary witnesses", "text": "Luke 2:1–21", "chapters": [[41, 2]], "start": 1, "end": 21, "kind": "story", "category": "Luke", "story": ["Joseph and Mary travel to Bethlehem for the registration, and Jesus is born there. Mary lays him in a manger. In the fields angels tell frightened shepherds where to find the Saviour and proclaim glory to God. The shepherds go quickly, find the child, and tell others what they heard. Mary keeps these things in her heart. On the eighth day the child is named Jesus."], "lesson": "The shepherds act on a sign they can go and check. Mary shows another faithful response by keeping and pondering what she hears.", "question": "What did the shepherds do between hearing the news and telling it to others?"},
  {"id": 91110, "title": "Simeon and Anna See the Child", "subtitle": "Waiting with hope and attention", "text": "Luke 2:22–40", "chapters": [[41, 2]], "start": 22, "end": 40, "kind": "story", "category": "Luke", "story": ["Mary and Joseph bring Jesus to the temple as the law requires. Simeon comes there led by the Spirit. Holding Jesus, he speaks of salvation for Israel and light for the Gentiles. He also tells Mary that sorrow will reach her. Anna, a widow who serves with prayer and fasting, gives thanks and speaks about the child to those awaiting redemption."], "lesson": "Years of prayer have attuned Simeon and Anna to what God is doing. Simeon's words put joy and coming sorrow before Mary together.", "question": "What had Simeon and Anna been waiting for, and how did each respond?"},
  {"id": 91111, "title": "Three Days Searching for Jesus", "subtitle": "Growing in wisdom and obedience", "text": "Luke 2:41–52", "chapters": [[41, 2]], "start": 41, "end": 52, "kind": "story", "category": "Luke", "story": ["On a visit to Jerusalem for Passover, twelve-year-old Jesus remains behind. Mary and Joseph search and find him among the teachers, listening and asking questions. Mary tells him how anxiously they have looked. Jesus speaks of his Father's concerns, which they do not understand. He returns to Nazareth with them and lives in obedience as he grows."], "lesson": "Luke records both Jesus' awareness of his Father and his obedience in the household. Mary keeps what she cannot yet explain and allows time for understanding.", "question": "What does Luke say Jesus did after the conversation at the temple?"},
  {"id": 91112, "title": "What Shall We Do?", "subtitle": "Repentance in daily dealings", "text": "Luke 3:1–20", "chapters": [[41, 3]], "start": 1, "end": 20, "kind": "story", "category": "Luke", "story": ["John preaches repentance and baptises in the Jordan region. People who ask how to respond receive practical answers. Those with extra clothing or food should share. Tax collectors must take only what is required, and soldiers must avoid extortion and be content with their pay. John points to the coming Christ and rebukes Herod, who puts him in prison."], "lesson": "John answers each group in terms of the power and goods already in its hands. Repentance reaches how people earn, speak, share and exercise authority.", "question": "What would a practical answer like John's sound like in your own work?"},
  {"id": 91113, "title": "The Son at Prayer", "subtitle": "Jesus and the human family", "text": "Luke 3:21–38", "chapters": [[41, 3]], "start": 21, "end": 38, "kind": "story", "category": "Luke", "story": ["As the baptised Jesus prays, heaven opens, the Holy Spirit descends like a dove and the Father's voice calls him the beloved Son. Luke then traces Jesus' family line through Joseph, as he was understood to be his son, through David and Abraham, and back beyond Israel to Adam and God."], "lesson": "Luke places a genealogy reaching to Adam beside the Father's declaration. The two passages give the reader a wide horizon for the ministry about to begin.", "question": "How does Luke's decision to trace the line to Adam widen the opening of the story?"},
  {"id": 91114, "title": "Three Tests in the Wilderness", "subtitle": "Obedience in hunger and weakness", "text": "Luke 4:1–13", "chapters": [[41, 4]], "start": 1, "end": 13, "kind": "story", "category": "Luke", "story": ["Jesus is led by the Spirit in the wilderness. Hungry after forty days, he answers the suggestion to make bread from stone with Scripture. Offered authority in return for worship, he insists that worship belongs to God. At Jerusalem the devil uses a promise from Scripture to urge him to leap from the temple. Jesus refuses to put God to the test."], "lesson": "Jesus meets both plain temptation and a temptation dressed in biblical words. His answers show how obedience holds Scripture together.", "question": "What is the difference between trusting God's promise and demanding proof of it?"},
  {"id": 91115, "title": "The Reading at Nazareth", "subtitle": "Receiving grace beyond familiar boundaries", "text": "Luke 4:14–30", "chapters": [[41, 4]], "start": 14, "end": 30, "kind": "story", "category": "Luke", "story": ["Jesus returns to Galilee and reads from Isaiah in Nazareth's synagogue. He announces that the promise has been fulfilled in their hearing. The listeners first wonder at his words. After he recalls Elijah's help to a widow outside Israel and Elisha's cleansing of Naaman, they become furious, drive him out and try to throw him down. He passes through them."], "lesson": "Jesus' neighbours are willing to hear gracious words until he speaks of grace reaching outsiders. Their reaction tests how we respond when God's kindness crosses our boundaries.", "question": "Why did the examples of the widow and Naaman matter to Jesus' hearers?"},
  {"id": 91116, "title": "An Open Door and Another Town", "subtitle": "Compassion and a clear purpose", "text": "Luke 4:31–44", "chapters": [[41, 4]], "start": 31, "end": 44, "kind": "story", "category": "Luke", "story": ["In Capernaum Jesus speaks with authority in the synagogue and delivers a man from an unclean spirit. At Simon's house he rebukes a fever, and the woman who was ill rises to serve. Many bring the sick at sunset. When the people try to keep Jesus with them the next day, he explains that he must preach the kingdom in other towns as well."], "lesson": "Jesus gives personal attention to sufferers while keeping his larger mission before him. Real need in one place does not cancel the call to serve elsewhere.", "question": "What reason does Jesus give when the people want him to stay?"},
  {"id": 91117, "title": "Nets That Nearly Break", "subtitle": "A call that reaches past unworthiness", "text": "Luke 5:1–16", "chapters": [[41, 5]], "start": 1, "end": 16, "kind": "story", "category": "Luke", "story": ["Jesus teaches from Simon's boat and then tells him to let down the nets. Simon has caught nothing all night, yet obeys. When the catch strains both boats, Simon falls before Jesus and confesses his sinfulness. Jesus tells him not to fear and calls him to a new work. Later a man with leprosy appeals to Jesus' willingness, and Jesus touches and cleanses him."], "lesson": "Simon and the man with leprosy each approach Jesus conscious of a barrier. Jesus answers one with a calling and the other with a touch.", "question": "Why does Simon's response to the catch go beyond gratitude for fish?"},
  {"id": 91118, "title": "A Man Lowered and a Tax Collector Called", "subtitle": "Forgiveness and a place at the table", "text": "Luke 5:17–39", "chapters": [[41, 5]], "start": 17, "end": 39, "kind": "story", "category": "Luke", "story": ["Men lower a paralysed man through the roof when they cannot reach Jesus through the crowd. He forgives the man, then restores his movement in answer to the objections of the teachers. Jesus calls Levi, who makes a feast for him. When challenged about the guests, he speaks of calling sinners to repentance. A question about fasting leads to pictures of a bridegroom, new cloth and new wine."], "lesson": "Jesus' choice to eat with people others shun belongs to his call to repentance. The healing and the feast both give visible form to his concern for people in need.", "question": "How does Jesus' picture of a physician explain his presence at Levi's table?"},
  {"id": 91119, "title": "A Sabbath Question and a Night of Prayer", "subtitle": "Mercy and the calling of the Twelve", "text": "Luke 6:1–19", "chapters": [[41, 6]], "start": 1, "end": 19, "kind": "story", "category": "Luke", "story": ["The disciples eat grain on a Sabbath and Jesus answers an objection from the story of David. On another Sabbath he calls a man with a withered hand to stand before everyone and restores it. Opposition grows. Jesus spends a night in prayer and then names the Twelve. He descends with them to a crowd seeking healing and instruction."], "lesson": "Luke places a night of prayer before a consequential choice. Public ministry and the calling of fellow workers arise alongside time spent before God.", "question": "What does Jesus do before choosing the Twelve, and how might that shape your own decisions?"},
  {"id": 91120, "title": "The Level Place and Two Foundations", "subtitle": "Mercy that reaches enemies", "text": "Luke 6:20–49", "chapters": [[41, 6]], "start": 20, "end": 49, "kind": "story", "category": "Luke", "story": ["Jesus blesses the poor, hungry and grieving and warns people satisfied with wealth and praise. He tells his hearers to love enemies and practise mercy as their Father does. He warns against correcting others while ignoring one's own fault and looks for good fruit from a good heart. He ends with houses built with and without a foundation."], "lesson": "The risk Jesus describes is hearing strong teaching and leaving ordinary conduct untouched. Mercy towards a person who cannot repay us is one place obedience becomes visible.", "question": "What would doing one instruction from this sermon look like before the week ends?"},
  {"id": 91121, "title": "A Servant and a Widow's Son", "subtitle": "Authority exercised with compassion", "text": "Luke 7:1–17", "chapters": [[41, 7]], "start": 1, "end": 17, "kind": "story", "category": "Luke", "story": ["A centurion sends friends who explain that Jesus need only speak for his servant to recover. Jesus marvels at his faith, and the messengers find the servant well. At Nain Jesus meets a funeral procession. Seeing the widow whose only son has died, he has compassion, stops the procession and restores the young man to his mother."], "lesson": "In Nain Jesus notices a grieving person before anyone asks him for help. The centurion's confidence in his authority is followed by an account of the compassion with which he uses it.", "question": "What about the widow's situation does Luke take care to tell you?"},
  {"id": 91122, "title": "John's Messengers Bring a Question", "subtitle": "Taking questions to Jesus", "text": "Luke 7:18–35", "chapters": [[41, 7]], "start": 18, "end": 35, "kind": "story", "category": "Luke", "story": ["John sends disciples to ask whether Jesus is the one to come. Jesus tells them to report the healings and good news they witness. After they leave, he describes John's calling. Some hearers had accepted John's baptism, while others had refused it. Jesus compares the generation to children who find fault with each other's choice of tune."], "lesson": "Jesus answers a serious question with evidence. His picture of children also exposes the habit of rejecting a messenger whatever he does.", "question": "What did Jesus give John's messengers to tell him on returning?"},
  {"id": 91123, "title": "Tears at Simon's Table", "subtitle": "Love that grows from forgiveness", "text": "Luke 7:36–50", "chapters": [[41, 7]], "start": 36, "end": 50, "kind": "story", "category": "Luke", "story": ["A woman enters Simon the Pharisee's house, wets Jesus' feet with tears, wipes them with her hair and anoints them. Simon questions what Jesus must know about her. Jesus tells of two debtors whose debts are cancelled, then compares the woman's attention with Simon's reception. He speaks forgiveness and sends her away in peace."], "lesson": "Simon classifies the woman by her past. Jesus makes her actions visible and asks Simon to consider the love that gratitude for mercy can produce.", "question": "Which acts of welcome does Jesus name when he turns Simon's attention to the woman?"},
  {"id": 91124, "title": "Women on the Road, Seed in the Soil", "subtitle": "Receiving the word and doing it", "text": "Luke 8:1–21", "chapters": [[41, 8]], "start": 1, "end": 21, "kind": "story", "category": "Luke", "story": ["Jesus travels with the Twelve and women who support the work from their resources. He tells the crowd about seed in four soils and explains how testing, cares and riches hinder fruit. A lamp belongs on a stand, and hearing deserves care. When his family cannot reach him through the crowd, he speaks of those who hear and do God's word."], "lesson": "Luke names people whose service made the travelling ministry possible. The teaching that follows calls for a response with the patience to bear fruit.", "question": "What does Jesus say marks the soil that brings fruit to maturity?"},
  {"id": 91125, "title": "Across the Storm to the Tombs", "subtitle": "Faith and testimony", "text": "Luke 8:22–39", "chapters": [[41, 8]], "start": 22, "end": 39, "kind": "story", "category": "Luke", "story": ["Jesus stills a storm after his frightened disciples wake him. Across the lake a man living among tombs meets him. The demons leave the man, enter pigs and the herd drowns. Local people find the man clothed and in his right mind but ask Jesus to leave. Jesus sends the man home to tell what God has done for him."], "lesson": "The restored man's neighbours have known his former condition. Jesus gives him a ministry among those who can see the change for themselves.", "question": "Why might the man's testimony matter particularly in his own home and town?"},
  {"id": 91126, "title": "The Woman Who Touched His Garment", "subtitle": "Care for a person hidden by the crowd", "text": "Luke 8:40–56", "chapters": [[41, 8]], "start": 40, "end": 56, "kind": "story", "category": "Luke", "story": ["Jairus begs Jesus to come to his dying daughter. While Jesus is on the way, a woman who has suffered bleeding for twelve years touches his garment. When he stops, she comes forward and tells what happened. He calls her daughter and sends her in peace. News arrives that Jairus's child has died. Jesus continues to the house, raises her and asks that she be given food."], "lesson": "Jesus gives both sufferers personal attention. The woman's public account allows the crowd to hear the peace he speaks to someone who could have gone away unnoticed.", "question": "What does the woman do after she realises that she cannot remain hidden?"},
  {"id": 91127, "title": "Sending the Twelve and Feeding the Crowd", "subtitle": "Serving from what God provides", "text": "Luke 9:1–17", "chapters": [[41, 9]], "start": 1, "end": 17, "kind": "story", "category": "Luke", "story": ["Jesus sends the Twelve to preach and heal. Herod hears conflicting reports and wonders who Jesus is. On returning, the apostles withdraw with Jesus, but people follow them. Jesus welcomes them, teaches and heals. At the end of the day the disciples bring five loaves and two fish. Jesus blesses and breaks the food, and they serve the crowd."], "lesson": "The disciples return from ministry and find another occasion to serve. Jesus welcomes the people who have interrupted their retreat and gives the disciples a part in feeding them.", "question": "How does Jesus respond to the crowd before there is any talk of bread?"},
  {"id": 91128, "title": "Peter's Answer and the Voice From the Cloud", "subtitle": "Hearing Jesus about the road ahead", "text": "Luke 9:18–36", "chapters": [[41, 9]], "start": 18, "end": 36, "kind": "story", "category": "Luke", "story": ["Peter calls Jesus the Christ of God. Jesus speaks of rejection, death and resurrection and calls his followers to take up their cross daily. Later, as he prays on a mountain, his appearance changes. Moses and Elijah speak of what he is to accomplish at Jerusalem. A cloud overshadows the disciples and a voice directs them to hear Jesus."], "lesson": "The conversation on the mountain concerns the road Jesus has already described. Glory and the costly work awaiting him belong together in Luke's account.", "question": "What subjects connect Jesus' first prediction with the conversation on the mountain?"},
  {"id": 91129, "title": "From the Mountain Towards Jerusalem", "subtitle": "Humility and a settled purpose", "text": "Luke 9:37–62", "chapters": [[41, 9]], "start": 37, "end": 62, "kind": "story", "category": "Luke", "story": ["Jesus heals a suffering boy the disciples could not help. He speaks again of being delivered into human hands. The disciples argue about rank, and Jesus sets a child near him. He corrects them for trying to stop someone acting in his name. As Jesus sets his face towards Jerusalem, a Samaritan village refuses him. He rebukes the disciples who want retaliation and speaks with people considering following him."], "lesson": "Several scenes show the disciples using rank, group identity or power to settle questions Jesus handles differently. His settled direction towards Jerusalem gives shape to his replies about following.", "question": "What responses does Jesus correct as the disciples move from the mountain to the road?"},
  {"id": 91130, "title": "The Messengers Return Rejoicing", "subtitle": "Joy rooted in belonging to God", "text": "Luke 10:1–24", "chapters": [[41, 10]], "start": 1, "end": 24, "kind": "story", "category": "Luke", "story": ["Jesus sends another group in pairs ahead of him. He tells them to seek the Lord of the harvest for workers, to receive hospitality and to declare the kingdom. When they return delighted that spirits obey them, Jesus turns their joy towards their names being written in heaven. He rejoices in the Spirit over what the Father has revealed."], "lesson": "The messengers have good reason to rejoice in what they have seen. Jesus directs them to a more lasting ground for joy than results they can report.", "question": "What reason for rejoicing does Jesus place above the success of their mission?"},
  {"id": 91131, "title": "The Good Samaritan", "subtitle": "Becoming a neighbour through mercy", "text": "Luke 10:25–37", "chapters": [[41, 10]], "start": 25, "end": 37, "kind": "story", "category": "Luke", "story": ["A lawyer asks Jesus what he must do to inherit eternal life. When the discussion reaches love of neighbour, the lawyer asks who counts as his neighbour. Jesus tells of a man stripped, beaten and left for dead on the road to Jericho. A priest and a Levite pass him. A Samaritan stops, treats the wounds, carries him to an inn and pays for his care. The lawyer identifies the neighbour as the one who showed mercy."], "lesson": "The Samaritan gives the injured man time, transport and money. Jesus directs the lawyer's attention to what it means to act as a neighbour when need is already in front of him.", "question": "Which of the Samaritan's actions required him to give up something of his own?"},
  {"id": 91132, "title": "At Martha's House", "subtitle": "Making room to listen to Jesus", "text": "Luke 10:38–42", "chapters": [[41, 10]], "start": 38, "end": 42, "kind": "story", "category": "Luke", "story": ["Martha welcomes Jesus into her house. As she becomes occupied with serving, her sister Mary sits at his feet and listens. Martha asks Jesus to tell Mary to help. Jesus answers that Martha is anxious and troubled about many things. He says Mary has chosen the good part and that it will not be taken from her."], "lesson": "Martha's welcome is real, and so is the strain she feels. Jesus names the distraction that can crowd out listening even when the work began as hospitality.", "question": "What was Mary doing when Martha asked Jesus to intervene?"},
  {"id": 91133, "title": "Teach Us to Pray", "subtitle": "Asking the Father with confidence", "text": "Luke 11:1–13", "chapters": [[41, 11]], "start": 1, "end": 13, "kind": "story", "category": "Luke", "story": ["After watching Jesus pray, a disciple asks for instruction. Jesus gives a prayer for the Father's name and kingdom, daily bread, forgiveness and deliverance. He tells of a man seeking bread from a friend at midnight, then encourages asking, seeking and knocking. The Father gives the Holy Spirit to those who ask him."], "lesson": "Jesus gives his disciples words for both large hopes and daily needs. The assurance of the Father's goodness gives persistence in prayer a personal basis.", "question": "How does the midnight request prepare you for what Jesus says about the Father?"},
  {"id": 91134, "title": "The Sign and the Lamp", "subtitle": "Taking care how you receive light", "text": "Luke 11:14–36", "chapters": [[41, 11]], "start": 14, "end": 36, "kind": "story", "category": "Luke", "story": ["When Jesus delivers a man who could not speak, some attribute the work to the ruler of demons. He answers that a divided kingdom falls and speaks of a stronger man overcoming an armed guard. He blesses those who hear God's word and keep it and recalls Jonah and the queen who came to Solomon. He warns his hearers to see that the light in them is genuine."], "lesson": "A demand for another sign can keep a person from facing the evidence already present. Jesus calls attention to the condition of those who are looking.", "question": "What does Jesus say Nineveh did when it had heard Jonah?"},
  {"id": 91135, "title": "The Meal That Exposed Hidden Burdens", "subtitle": "Justice and love alongside religious care", "text": "Luke 11:37–54", "chapters": [[41, 11]], "start": 37, "end": 54, "kind": "story", "category": "Luke", "story": ["A Pharisee notices Jesus has not washed before a meal. Jesus speaks of clean outsides and neglected hearts. He names injustice, disregard for the love of God and a taste for public honour. When a lawyer objects, Jesus addresses the burdens imposed on people and the removal of the key of knowledge. His hosts begin pressing him for words they can use against him."], "lesson": "A person can take care over visible duties and leave a neighbour under an unnecessary burden. Jesus connects knowledge and authority with responsibility for what they do to others.", "question": "Which matters did Jesus say were neglected while people paid attention to small tithes?"},
  {"id": 91136, "title": "Barns, Ravens and an Inheritance", "subtitle": "Trust when possessions promise security", "text": "Luke 12:1–34", "chapters": [[41, 12]], "start": 1, "end": 34, "kind": "story", "category": "Luke", "story": ["Jesus warns against hypocrisy and fear. A request about an inheritance prompts the story of a rich man who builds larger barns, only to die before he enjoys them. Jesus asks his disciples to consider ravens and lilies and to seek the kingdom. He reminds them of the Father's care and connects the location of treasure with the heart."], "lesson": "The man in the parable makes plans that centre on his own stores. Jesus gives his disciples a different way to reckon with provision, generosity and the future.", "question": "What did the rich man leave out of the conversation he had with himself?"},
  {"id": 91137, "title": "The Lamps and the Changing Weather", "subtitle": "Faithfulness while there is time", "text": "Luke 12:35–59", "chapters": [[41, 12]], "start": 35, "end": 59, "kind": "story", "category": "Luke", "story": ["Jesus pictures servants waiting with lamps lit and a steward entrusted with a household. Peter asks whom the parable concerns. Jesus speaks of the responsibility that grows with what a person has received. He describes the division his coming will bring and challenges people who can read the weather but fail to judge their own situation. He urges settlement before reaching the court."], "lesson": "The faithful steward uses his authority to care for people during the master's absence. Jesus' urgency concerns decisions a hearer can still make today.", "question": "What does the faithful steward give the household, and when does he give it?"},
  {"id": 91138, "title": "A Fig Tree Granted Time and a Woman Set Free", "subtitle": "Repentance and mercy without delay", "text": "Luke 13:1–17", "chapters": [[41, 13]], "start": 1, "end": 17, "kind": "story", "category": "Luke", "story": ["Reports of people killed lead Jesus to challenge the idea that victims were worse sinners. He speaks of a fig tree given more time to bear fruit. In a synagogue he sees a woman who has been bent over for years and sets her free. When the ruler objects to a Sabbath healing, Jesus asks why a daughter of Abraham should remain bound."], "lesson": "More time in the parable comes with attention to bearing fruit. In the synagogue Jesus uses the time at hand to relieve a person's suffering.", "question": "How do the gardener and Jesus each respond to a need that has lasted a long time?"},
  {"id": 91139, "title": "A Narrow Door and a Lament", "subtitle": "Responding while the door is open", "text": "Luke 13:18–35", "chapters": [[41, 13]], "start": 18, "end": 35, "kind": "story", "category": "Luke", "story": ["Jesus compares the kingdom to a mustard seed and leaven. As he travels towards Jerusalem, a question about how many will be saved leads him to urge entry through a narrow door. He speaks of people coming from every direction to sit in the kingdom. Warned about Herod, he continues his journey and laments over Jerusalem, longing to gather its children."], "lesson": "Jesus answers speculation with a call to respond. His lament gives us a view of the compassion behind the urgency of his words.", "question": "How does Jesus redirect the question about who will be saved?"},
  {"id": 91140, "title": "Places at the Table and an Open Invitation", "subtitle": "Hospitality that expects no repayment", "text": "Luke 14:1–24", "chapters": [[41, 14]], "start": 1, "end": 24, "kind": "story", "category": "Luke", "story": ["Jesus heals a man at a Sabbath meal and asks his hosts how they would respond to an emergency. Seeing guests choose places of honour, he tells them to take a lower seat. He urges hosts to invite people who cannot repay them. Then he tells of a feast whose first guests make excuses, so the invitation goes out through streets and lanes."], "lesson": "Jesus speaks to the people choosing seats and to the people choosing guests. His teaching gives hospitality a purpose beyond rank and repayment.", "question": "Who would receive an invitation if you followed Jesus' advice to the host?"},
  {"id": 91141, "title": "Before You Build the Tower", "subtitle": "Counting the cost of discipleship", "text": "Luke 14:25–35", "chapters": [[41, 14]], "start": 25, "end": 35, "kind": "story", "category": "Luke", "story": ["Crowds are travelling with Jesus when he speaks plainly about loyalty to him and carrying a cross. He tells them to picture a builder calculating the cost and a king considering what his forces can face. He then speaks of relinquishing possessions and of salt that has lost its usefulness."], "lesson": "Jesus respects his hearers enough to tell them what following will demand. Counting the cost gives substance to the commitment they are considering.", "question": "Why does Jesus speak of the builder before saying what a disciple must be ready to give up?"},
  {"id": 91142, "title": "The Sheep and the Coin", "subtitle": "Joy in finding the lost", "text": "Luke 15:1–10", "chapters": [[41, 15]], "start": 1, "end": 10, "kind": "story", "category": "Luke", "story": ["People regarded as sinners come near to hear Jesus. Some religious leaders complain that he receives and eats with them. He answers with a shepherd who searches for a lost sheep and a woman who sweeps her house for a lost coin. Each calls others to rejoice when what was missing is found."], "lesson": "Both searchers take the initiative. Jesus uses their joy to challenge people who resented his welcome of those who needed repentance.", "question": "What do the shepherd and the woman both do as soon as they find what was lost?"},
  {"id": 91143, "title": "The Father Goes Out to Both Sons", "subtitle": "Repentance, welcome and resentment", "text": "Luke 15:11–32", "chapters": [[41, 15]], "start": 11, "end": 32, "kind": "story", "category": "Luke", "story": ["A younger son takes his share and wastes it far from home. In hunger he resolves to return and confess. His father sees him at a distance, runs to meet him and celebrates his return. The older brother hears the music and refuses to enter. The father goes out to him as well and explains why they must rejoice."], "lesson": "The father approaches both sons, each at a different distance from the feast. The older son's words help us notice the resentment that can grow alongside outward service.", "question": "What does the father say to the older son about why the feast is necessary?"},
  {"id": 91144, "title": "The Steward Facing Dismissal", "subtitle": "Stewardship with the future in view", "text": "Luke 16:1–18", "chapters": [[41, 16]], "start": 1, "end": 18, "kind": "story", "category": "Luke", "story": ["A steward learns he must account for his management. He reduces debts owed to his master so that people may receive him later. The master acknowledges the steward's shrewdness. Jesus turns the picture towards faithfulness with money, warns that two masters cannot be served and answers those who justify themselves before others. He then speaks of the law and of marriage."], "lesson": "The steward acts decisively because he knows an accounting is coming. Jesus connects that foresight with faithful conduct in the small responsibilities we already have.", "question": "Which qualities does Jesus demand of his hearers after describing the steward's shrewdness?"},
  {"id": 91145, "title": "The Man at the Gate", "subtitle": "Listening before the opportunity passes", "text": "Luke 16:19–31", "chapters": [[41, 16]], "start": 19, "end": 31, "kind": "story", "category": "Luke", "story": ["A rich man feasts while Lazarus lies sick and hungry at his gate. Both die, and their conditions are reversed. The rich man asks Abraham for relief, then for Lazarus to warn his brothers. Abraham tells him they have Moses and the prophets. If they refuse to listen to them, even a messenger rising from the dead will fail to persuade them."], "lesson": "The gate places the rich man's responsibility near enough to see each day. Abraham's reply presses the living reader to act on the instruction already given.", "question": "What opportunity did the rich man have while Lazarus still lay at his gate?"},
  {"id": 91146, "title": "The One Who Returned", "subtitle": "Mercy received with gratitude", "text": "Luke 17:1–19", "chapters": [[41, 17]], "start": 1, "end": 19, "kind": "story", "category": "Luke", "story": ["Jesus warns about causing another to stumble, calls for repeated forgiveness and speaks of faith and service. On the road ten men with leprosy call from a distance. He sends them to the priests and they are cleansed as they go. One comes back praising God and thanks Jesus. Luke identifies him as a Samaritan."], "lesson": "All ten act on Jesus' instruction. One also turns back to acknowledge the mercy received. Gratitude gives us a way to remember who helped us.", "question": "What does the Samaritan do that brings him back to Jesus after the healing?"},
  {"id": 91147, "title": "The Kingdom and the Days of Noah", "subtitle": "Readiness in ordinary life", "text": "Luke 17:20–37", "chapters": [[41, 17]], "start": 20, "end": 37, "kind": "story", "category": "Luke", "story": ["Pharisees ask when the kingdom will come. Jesus refuses to give them a place to point to and then speaks to his disciples about the days of the Son of Man. He warns against reports that send them chasing after him. He recalls people living ordinary lives before the flood and before the judgement of Sodom, and tells them to remember Lot's wife."], "lesson": "Daily routines can occupy the whole field of attention. Jesus gives ordinary life a wider horizon by calling people to remember where their deepest loyalties lie.", "question": "Which everyday activities does Jesus name, and what do they reveal about the suddenness of what followed?"},
  {"id": 91148, "title": "The Widow Who Kept Coming", "subtitle": "Prayer without losing heart", "text": "Luke 18:1–8", "chapters": [[41, 18]], "start": 1, "end": 8, "kind": "story", "category": "Luke", "story": ["A widow repeatedly asks a judge to give her justice against her adversary. He cares for neither God nor people and refuses for a time. Eventually he grants her request because she keeps coming. Jesus asks his hearers to consider how much more God will attend to those who cry to him day and night. He ends with a question about whether faith will be found when the Son of Man comes."], "lesson": "Jesus introduces the story as instruction to pray and persevere. The widow's persistence gives shape to a kind of faith that continues through delay.", "question": "What does the judge admit about his motives, and how does Jesus contrast his response with God's care?"},
  {"id": 91149, "title": "Two Prayers and the Children", "subtitle": "Coming to God without a claim to rank", "text": "Luke 18:9–17", "chapters": [[41, 18]], "start": 9, "end": 17, "kind": "story", "category": "Luke", "story": ["Jesus pictures two men going to the temple to pray. A Pharisee lists his practices and compares himself favourably with others. A tax collector stands at a distance and asks God for mercy. Jesus says the tax collector goes home justified. Later, when the disciples rebuke people bringing babies, Jesus welcomes the children and speaks of receiving the kingdom like a child."], "lesson": "The tax collector brings a need before God. Jesus' welcome of the children gives dependence a visible form and challenges those who think they must establish their standing first.", "question": "What is each man relying on as he prays?"},
  {"id": 91150, "title": "Two Men Asking Jesus a Question", "subtitle": "Seeing what stands in the way", "text": "Luke 18:18–43", "chapters": [[41, 18]], "start": 18, "end": 43, "kind": "story", "category": "Luke", "story": ["A ruler asks about eternal life. He grows sorrowful when Jesus asks him to distribute his wealth and follow. Jesus speaks of what God makes possible and tells the Twelve again about his coming suffering. Near Jericho a blind man calls for mercy while people try to quiet him. Jesus stops, asks his desire and restores his sight. The man follows, praising God."], "lesson": "The ruler becomes very sad after hearing what following would cost. The healed man follows and praises God. Their responses prompt reflection on what we do after Jesus answers.", "question": "How does the blind man's response differ from that of the ruler?"},
  {"id": 91151, "title": "Jesus Stops Under Zacchaeus's Tree", "subtitle": "Repentance that makes restitution", "text": "Luke 19:1–10", "chapters": [[41, 19]], "start": 1, "end": 10, "kind": "story", "category": "Luke", "story": ["Zacchaeus is a wealthy chief tax collector in Jericho. Being short, he climbs a tree to see Jesus over the crowd. Jesus calls him down and says he will stay at his house. People complain that Jesus has gone to be the guest of a sinner. Zacchaeus speaks of giving to the poor and restoring what he took wrongfully. Jesus announces salvation to the house and speaks of seeking and saving the lost."], "lesson": "Jesus' welcome comes before the public promise of restitution. Zacchaeus then names ways to repair wrongdoing that the people affected can actually experience.", "question": "What does Zacchaeus say he will give to the poor and restore to those he wronged?"},
  {"id": 91152, "title": "The Nobleman and the Money Entrusted", "subtitle": "Using what you have while the king is away", "text": "Luke 19:11–27", "chapters": [[41, 19]], "start": 11, "end": 27, "kind": "story", "category": "Luke", "story": ["As Jesus draws near to Jerusalem, people expect God's kingdom to appear immediately. Jesus tells of a nobleman who goes away to receive a kingdom and leaves money with servants. Some citizens oppose his rule. When he returns, he asks what the servants have done. Some have gained more, while one has hidden the money and appeals to fear as his reason."], "lesson": "Jesus places responsibility inside the waiting period. The servants' work takes place before they can see the nobleman return and settle accounts.", "question": "What does the master ask the servants to do with the time and resources they have?"},
  {"id": 91153, "title": "Praise on the Road and Tears for the City", "subtitle": "Recognising the time of visitation", "text": "Luke 19:28–48", "chapters": [[41, 19]], "start": 28, "end": 48, "kind": "story", "category": "Luke", "story": ["Crowds of disciples praise God as Jesus approaches Jerusalem on a colt. Some Pharisees ask him to silence them. He answers that stones would cry out. When he sees the city, he weeps and speaks of its failure to recognise what would bring peace. In the temple he drives out traders and teaches daily as leaders look for a way to destroy him."], "lesson": "The praise of the disciples and Jesus' grief belong to the same arrival. His tears reveal how deeply he cares about a city that fails to receive what he brings.", "question": "What does Jesus see about Jerusalem that the rejoicing crowd may have missed?"},
  {"id": 91154, "title": "Who Gave You Authority?", "subtitle": "Giving God what belongs to God", "text": "Luke 20:1–26", "chapters": [[41, 20]], "start": 1, "end": 26, "kind": "story", "category": "Luke", "story": ["Temple leaders ask Jesus for his authority. He asks them about John's baptism, and they refuse to commit themselves. He tells of tenants who mistreat servants and kill the owner's son. Then spies ask about tribute to Caesar. Jesus examines the coin's image and tells them to give Caesar and God what belongs to each."], "lesson": "The tenants treat an entrusted vineyard as if it were theirs to seize. The question about the coin gives the hearer another opportunity to consider what belongs to God.", "question": "What do the tenants refuse to acknowledge when the owner sends for fruit?"},
  {"id": 91155, "title": "The Living God and Honour in Public", "subtitle": "Reading Scripture with humility", "text": "Luke 20:27–47", "chapters": [[41, 20]], "start": 27, "end": 47, "kind": "story", "category": "Luke", "story": ["Sadducees ask Jesus a question about marriage and resurrection. He answers from God's words to Moses and speaks of a life beyond death. Jesus then asks why David calls the Christ Lord. As the people listen, he warns his disciples about teachers who seek greetings, seats and honour while using long prayers as a cover for taking advantage of widows."], "lesson": "Jesus gives Scripture careful attention and condemns the use of a religious appearance to hide harm. Humility in interpretation should be joined to honesty in conduct.", "question": "What activity did Jesus warn could be used to cover harm to widows?"},
  {"id": 91156, "title": "Two Small Coins and Great Stones", "subtitle": "Faithfulness when appearances change", "text": "Luke 21:1–19", "chapters": [[41, 21]], "start": 1, "end": 19, "kind": "story", "category": "Luke", "story": ["Jesus watches a poor widow put two small coins into the treasury and draws attention to what the gift costs her. When people admire the temple, he says its stones will fall. He warns of false claims, upheaval and persecution. When his followers are brought before authorities, they will have an opportunity to bear witness."], "lesson": "The widow's small gift receives Jesus' notice beside a building that appears permanent. His teaching gives lasting weight to faithfulness in moments others may discount.", "question": "What does Jesus see in the widow's gift that a person admiring the temple might overlook?"},
  {"id": 91157, "title": "Jerusalem Surrounded and the Call to Watch", "subtitle": "Prayer when hearts grow heavy", "text": "Luke 21:20–38", "chapters": [[41, 21]], "start": 20, "end": 38, "kind": "story", "category": "Luke", "story": ["Jesus prepares his hearers for Jerusalem surrounded by armies. He speaks of distress and of signs accompanying the coming of the Son of Man. He tells them to take heed lest excess or the cares of life weigh down their hearts. Luke closes the scene with people coming early to hear him teach at the temple."], "lesson": "The trouble Jesus describes is public, but he identifies a danger within the hearer as well. Prayer and alertness keep cares from occupying the heart entirely.", "question": "Which things does Jesus say can weigh down a person's heart?"},
  {"id": 91158, "title": "The Meal Prepared in Jerusalem", "subtitle": "Receiving and remembering Jesus' gift", "text": "Luke 22:1–23", "chapters": [[41, 22]], "start": 1, "end": 23, "kind": "story", "category": "Luke", "story": ["The leaders seek a way to kill Jesus. Judas agrees to help them. Peter and John follow Jesus' directions to a furnished room and prepare the Passover. At the meal Jesus breaks bread and shares a cup, speaking of his body and of the covenant in his blood. He announces that his betrayer is at the table."], "lesson": "Luke places a meal of remembrance in a setting where betrayal is already under way. Jesus speaks of giving himself while those around him are questioning what one of them might do.", "question": "What instructions did Peter and John follow before the meal where Jesus spoke of remembering him?"},
  {"id": 91159, "title": "A Servant at the Table and Prayer on the Mount", "subtitle": "Praying through weakness", "text": "Luke 22:24–46", "chapters": [[41, 22]], "start": 24, "end": 46, "kind": "story", "category": "Luke", "story": ["The disciples dispute who is greatest. Jesus describes himself as one who serves and tells Simon that he has prayed for his faith. Peter protests that he is ready for prison and death. On the Mount of Olives Jesus urges prayer, asks the Father about the cup and yields to his will. He finds the disciples sleeping from sorrow."], "lesson": "Jesus sees the weakness behind Peter's confident words. He also looks ahead to Peter's return and gives him the work of strengthening others.", "question": "What does Jesus ask Peter to do after he has turned back?"},
  {"id": 91160, "title": "A Healed Ear and a Remembered Word", "subtitle": "Mercy and truth at the point of failure", "text": "Luke 22:47–71", "chapters": [[41, 22]], "start": 47, "end": 71, "kind": "story", "category": "Luke", "story": ["Judas approaches with a kiss. During the arrest a disciple strikes the high priest's servant, and Jesus heals the man's ear. Peter follows at a distance and denies knowing Jesus three times. When the rooster crows, Jesus looks at him. Peter remembers the warning and weeps. Jesus endures mockery and answers the council's questions about his identity."], "lesson": "Jesus heals someone on the side arresting him. Peter receives a look that brings the truth of Jesus' words home to him.", "question": "Which moments in this passage show Jesus giving attention to people around him while he himself is under arrest?"},
  {"id": 91161, "title": "Between Pilate and Herod", "subtitle": "Responsibility for an unjust decision", "text": "Luke 23:1–25", "chapters": [[41, 23]], "start": 1, "end": 25, "kind": "story", "category": "Luke", "story": ["Leaders bring accusations before Pilate. Hearing that Jesus is from Galilee, Pilate sends him to Herod. Herod hopes to see a miracle, questions and mocks him, then sends him back. Pilate repeatedly says he has found no cause for death. The crowd insists on Barabbas's release and Jesus' crucifixion. Pilate gives them what they demand."], "lesson": "Pilate's own stated finding makes his eventual decision harder to excuse. The sequence asks how far a person will carry a truthful judgement when the people around him insist otherwise.", "question": "What does Pilate say he found, and what does he finally do?"},
  {"id": 91162, "title": "The Road to the Cross and the Man Beside Jesus", "subtitle": "A plea for mercy at the last hour", "text": "Luke 23:26–43", "chapters": [[41, 23]], "start": 26, "end": 43, "kind": "story", "category": "Luke", "story": ["Soldiers lay Jesus' cross on Simon of Cyrene. Jesus speaks to the grieving women following him. At the place of execution Jesus is crucified with two criminals and prays for forgiveness. One criminal mocks him. The other acknowledges his own guilt and asks Jesus to remember him when he comes into his kingdom. Jesus promises him a place in paradise."], "lesson": "The second man brings no record of service to commend himself. He acknowledges the truth about his condition and addresses Jesus with a plain request.", "question": "How does the second criminal describe himself and Jesus before making his request?"},
  {"id": 91163, "title": "The Last Prayer and the Borrowed Tomb", "subtitle": "Faithful care in grief", "text": "Luke 23:44–56", "chapters": [[41, 23]], "start": 44, "end": 56, "kind": "story", "category": "Luke", "story": ["Darkness comes over the land and the temple curtain tears. Jesus commits his spirit into his Father's hands and dies. A centurion responds by glorifying God. Joseph of Arimathea, who had not agreed with the council, asks Pilate for the body and lays it in a tomb. Women from Galilee see the burial and prepare ointments before resting on the Sabbath."], "lesson": "Joseph uses what opportunity remains to care for Jesus' body. The women attend to the burial carefully enough to return to the place.", "question": "What does Luke tell you about Joseph's earlier decision and his action after Jesus dies?"},
  {"id": 91164, "title": "The Women Remember His Words", "subtitle": "Hope remembered amid confusion", "text": "Luke 24:1–12", "chapters": [[41, 24]], "start": 1, "end": 12, "kind": "story", "category": "Luke", "story": ["Women bring spices to the tomb and find the stone rolled away and the body gone. Two men in shining clothing remind them what Jesus said in Galilee about his death and rising. The women remember and tell the apostles. Their report is dismissed. Peter runs to the tomb and leaves wondering about what he has seen."], "lesson": "The messengers draw the women's attention to words they have already heard. Those words allow them to understand the empty place before others believe their report.", "question": "Which part of Jesus' earlier teaching do the women remember at the tomb?"},
  {"id": 91165, "title": "A Stranger on the Road to Emmaus", "subtitle": "Reading disappointment in the light of Scripture", "text": "Luke 24:13–35", "chapters": [[41, 24]], "start": 13, "end": 35, "kind": "story", "category": "Luke", "story": ["Two disciples tell a travelling companion about Jesus' death and their disappointed hope. He opens the Scriptures to show why the Christ would suffer and enter glory. They urge him to stay. At the meal they recognise Jesus when he breaks the bread, and he disappears from their sight. They return to Jerusalem and tell what happened on the way."], "lesson": "Jesus listens to their account of disappointment, then teaches them to read events through Scripture. Their return to Jerusalem shows what changes when the story they thought had ended opens again.", "question": "What is different in the two disciples' understanding by the time they return to Jerusalem?"},
  {"id": 91166, "title": "An Opened Understanding and the Parting Blessing", "subtitle": "Witness grounded in what Jesus has done", "text": "Luke 24:36–53", "chapters": [[41, 24]], "start": 36, "end": 53, "kind": "story", "category": "Luke", "story": ["Jesus appears while the disciples are talking. They are frightened, so he shows them his hands and feet and eats before them. He opens their understanding of the Scriptures and speaks of repentance and forgiveness being proclaimed to all nations. He tells them to wait for power from on high. Near Bethany he blesses them as he is carried up. They return to Jerusalem with joy."], "lesson": "Jesus grounds their witness in what they have seen and in what Scripture explains. He also calls them to wait for what the Father has promised before beginning their work.", "question": "What does Jesus tell the disciples to proclaim, and what does he tell them to wait for?"},
  {"id": 91167, "title": "The Word Comes to Dwell Among Us", "subtitle": "Receiving the One who makes the Father known", "text": "John 1:1–18", "chapters": [[42, 1]], "start": 1, "end": 18, "kind": "story", "category": "John", "story": ["John begins before creation, with the Word who was with God and was God. All things came into being through him. John the Baptist came to bear witness to the light. The world did not recognise the Word, but those who received him were given the right to become children of God. The Word became flesh and dwelt among us, making the Father known."], "lesson": "The opening puts God's initiative before any human response. Receiving Jesus begins with recognising who has come and what he makes known.", "question": "What does the opening tell you about the Word before it describes his coming into the world?"},
  {"id": 91168, "title": "A Witness at the Jordan", "subtitle": "Directing attention to Jesus", "text": "John 1:19–34", "chapters": [[42, 1]], "start": 19, "end": 34, "kind": "story", "category": "John", "story": ["Messengers ask John who he is. He denies that he is the Christ and describes himself as a voice preparing the Lord's way. He says someone stands among them whom they do not know. On seeing Jesus the next day, he calls him the Lamb of God and tells how the Spirit descended and remained on him."], "lesson": "John speaks plainly about the limits of his own role. His testimony gives the people a person to look towards beyond the man baptising them.", "question": "What does John say about Jesus that explains why his own work points beyond himself?"},
  {"id": 91169, "title": "Come and See", "subtitle": "The first steps of discipleship", "text": "John 1:35–51", "chapters": [[42, 1]], "start": 35, "end": 51, "kind": "story", "category": "John", "story": ["Two of John's disciples follow Jesus after hearing John's testimony. Jesus asks what they seek and invites them to see where he is staying. Andrew brings his brother Simon. Jesus calls Philip, who tells Nathanael. Nathanael questions whether anything good can come from Nazareth, but comes when Philip invites him. Jesus speaks of seeing him earlier under the fig tree."], "lesson": "Philip answers a doubt with an invitation to meet Jesus. The first followers discover more by coming near, listening and bringing others.", "question": "How does Philip respond to Nathanael's objection about Nazareth?"},
  {"id": 91170, "title": "The Jars at the Wedding", "subtitle": "Obedience before the outcome is visible", "text": "John 2:1–12", "chapters": [[42, 2]], "start": 1, "end": 12, "kind": "story", "category": "John", "story": ["At a wedding in Cana the wine runs out. Jesus' mother brings the matter to him and tells the servants to do what he says. He directs them to fill six stone jars with water and take some to the steward. The steward tastes wine and remarks on its quality. John calls this the first sign through which Jesus shows his glory."], "lesson": "The servants fill the jars before knowing what the steward will taste. John directs the reader past the immediate relief at the wedding to the glory the disciples begin to see.", "question": "Who knew where the wine came from, and what does John say the disciples did in response?"},
  {"id": 91171, "title": "The Temple at Passover", "subtitle": "Worship and the sign Jesus gives", "text": "John 2:13–25", "chapters": [[42, 2]], "start": 13, "end": 25, "kind": "story", "category": "John", "story": ["Jesus goes up to Jerusalem and finds traders and money changers in the temple. He drives them out and speaks of his Father's house. When challenged for a sign, he speaks of raising the temple in three days. His hearers think of the building. John explains that Jesus meant his body, something the disciples remember after the resurrection."], "lesson": "Understanding sometimes arrives when an earlier saying is read in light of later events. John tells us the disciples remembered both Scripture and Jesus' words.", "question": "Why did Jesus' hearers and his disciples understand the temple saying differently?"},
  {"id": 91172, "title": "Nicodemus Comes at Night", "subtitle": "New birth and coming into the light", "text": "John 3:1–21", "chapters": [[42, 3]], "start": 1, "end": 21, "kind": "story", "category": "John", "story": ["Nicodemus visits Jesus at night, acknowledging the signs. Jesus speaks of being born again, and Nicodemus asks how that can happen. Jesus describes birth by the Spirit and compares the Spirit's work to the wind. He recalls Moses lifting up the serpent and speaks of the Son being lifted up, of God's love for the world and of the choice to come into the light."], "lesson": "Nicodemus brings knowledge and recognised standing to the conversation. Jesus directs him to life the Spirit gives and to a response that allows deeds to come into the light.", "question": "What makes Nicodemus's first understanding of birth inadequate for what Jesus is saying?"},
  {"id": 91173, "title": "The Friend of the Bridegroom", "subtitle": "Joy when another takes the greater place", "text": "John 3:22–36", "chapters": [[42, 3]], "start": 22, "end": 36, "kind": "story", "category": "John", "story": ["While Jesus' disciples are baptising and John is still at work, some of John's followers worry that people are going to Jesus. John reminds them that he was sent ahead of the Christ. He describes himself as the friend rejoicing at the bridegroom's voice. He speaks of Jesus increasing and of eternal life for the one who believes in the Son."], "lesson": "John's joy depends on the bridegroom being heard. His disciples' concern gives him a chance to explain success in terms of the work he was given.", "question": "What makes John rejoice in the very news that concerns his followers?"},
  {"id": 91174, "title": "A Conversation Beside Jacob's Well", "subtitle": "Living water and truthful worship", "text": "John 4:1–26", "chapters": [[42, 4]], "start": 1, "end": 26, "kind": "story", "category": "John", "story": ["Jesus, tired from travelling, asks a Samaritan woman for water. She is surprised that a Jewish man speaks to her. He speaks of living water and brings her circumstances into the conversation. She asks about the proper place of worship. Jesus says the Father seeks worshippers in spirit and truth. When she speaks of the coming Messiah, he identifies himself to her."], "lesson": "Jesus speaks about worship to someone whose life and community have made the meeting unusual. He brings truth about her circumstances and the offer of living water into the same conversation.", "question": "How does Jesus answer the question about the place of worship?"},
  {"id": 91175, "title": "The Woman Leaves Her Water Pot", "subtitle": "Witness and a harvest already waiting", "text": "John 4:27–42", "chapters": [[42, 4]], "start": 27, "end": 42, "kind": "story", "category": "John", "story": ["The disciples return and wonder at the conversation. The woman leaves her water pot, goes into the town and calls people to meet Jesus. Meanwhile Jesus tells the disciples that doing his Father's work is his food and asks them to look at the fields ready for harvest. Many initially believe through the woman's testimony, then hear Jesus for themselves."], "lesson": "The woman gives her neighbours a reason to come. Their own hearing deepens what began with her report.", "question": "What two stages does John describe in the townspeople's response?"},
  {"id": 91176, "title": "The Father Who Went Home on a Word", "subtitle": "Trust before confirmation arrives", "text": "John 4:43–54", "chapters": [[42, 4]], "start": 43, "end": 54, "kind": "story", "category": "John", "story": ["Back in Galilee, an official asks Jesus to come heal his son in Capernaum. Jesus tells him his son lives. The man believes the word and starts home. Servants meet him with news of the recovery. When he asks when the fever broke, he learns it happened at the hour Jesus spoke, and his household believes."], "lesson": "The father must decide how to act while he is still away from his son. The journey home gives his trust a practical form before he learns the hour of the healing.", "question": "At what point did the father begin to act on what Jesus told him?"},
  {"id": 91177, "title": "The Man Who Carried His Bed", "subtitle": "Receiving help after long waiting", "text": "John 5:1–18", "chapters": [[42, 5]], "start": 1, "end": 18, "kind": "story", "category": "John", "story": ["At a pool in Jerusalem Jesus sees a man who has been ill for thirty-eight years. Jesus asks whether he wants to be made well. The man explains that he has no one to help him into the water. Jesus tells him to rise, take up his bed and walk. Because it is the Sabbath, the man is questioned about carrying it. Jesus later speaks to him in the temple and answers his critics about his Father's work."], "lesson": "A man who has described years of frustrated hope rises at Jesus' word. The dispute that follows shows how easily a healed person can become secondary to an argument.", "question": "What does the man say about his situation before Jesus tells him to rise?"},
  {"id": 91178, "title": "The Witnesses Jesus Names", "subtitle": "Reading Scripture with willingness to come", "text": "John 5:19–47", "chapters": [[42, 5]], "start": 19, "end": 47, "kind": "story", "category": "John", "story": ["Jesus speaks of doing his Father's work and of the Son giving life and exercising judgement. He names witnesses: John, the works the Father gave him, the Father himself and Scripture. He tells his hearers that they search the Scriptures while refusing to come to the one of whom those Scriptures testify. He also speaks of Moses as a witness."], "lesson": "Searching Scripture calls for willingness to respond to what it reveals. Jesus connects the hearers' reception of him with the glory they seek from one another.", "question": "Which witnesses does Jesus name, and what response does he find missing?"},
  {"id": 91179, "title": "The Boy's Lunch and the Boat at Night", "subtitle": "Jesus knows the need before the disciples do", "text": "John 6:1–21", "chapters": [[42, 6]], "start": 1, "end": 21, "kind": "story", "category": "John", "story": ["Seeing a crowd, Jesus asks Philip where bread can be bought. Philip counts the expense, and Andrew mentions a boy with five loaves and two fish. Jesus gives thanks and feeds the people. They want to make him king, so he withdraws. At night the disciples row against rough water. Jesus comes to them on the water and tells them who he is."], "lesson": "Philip's estimate and Andrew's small find are both honest. Jesus has a purpose beyond their calculations and declines the kingship the crowd tries to impose.", "question": "What reasons for fear or concern appear in the feeding and in the crossing?"},
  {"id": 91180, "title": "Bread That Gives Life", "subtitle": "Seeking Jesus beyond a full stomach", "text": "John 6:22–40", "chapters": [[42, 6]], "start": 22, "end": 40, "kind": "story", "category": "John", "story": ["People cross the lake looking for Jesus after the feeding. He tells them they are seeking him because they ate and were filled. He turns the conversation towards food that endures, believing in the one the Father sent and bread coming from heaven. He calls himself the bread of life and promises to receive those who come to him."], "lesson": "The crowd has received real food and wants more. Jesus uses that need to speak about a deeper hunger and about the life he gives.", "question": "What reason does Jesus give for the crowd's search, and where does he direct it?"},
  {"id": 91181, "title": "When Many Turned Back", "subtitle": "Staying when Jesus' words are hard", "text": "John 6:41–71", "chapters": [[42, 6]], "start": 41, "end": 71, "kind": "story", "category": "John", "story": ["Listeners object to Jesus' claim to have come from heaven. He speaks of being drawn by the Father and uses the language of eating his flesh and drinking his blood. Many disciples call the saying hard and leave. When Jesus asks the Twelve if they will go, Peter answers that Jesus has the words of eternal life. John then draws attention to the coming betrayal."], "lesson": "Peter's reply is a confession about where he has found life. John leaves the departure of many and the future betrayal in view, so that remaining cannot be reduced to standing with the crowd.", "question": "What ground does Peter give for staying with Jesus?"},
  {"id": 91182, "title": "A Journey Made Quietly", "subtitle": "Judging with care", "text": "John 7:1–24", "chapters": [[42, 7]], "start": 1, "end": 24, "kind": "story", "category": "John", "story": ["Jesus' brothers urge him to show his works publicly at the feast. He does not go with them, then goes quietly. People discuss him in low voices. When he teaches in the temple, he says his teaching comes from the one who sent him. He answers objections about a Sabbath healing and calls his listeners to judge rightly."], "lesson": "Jesus gives little weight to the demand to establish himself by publicity. His instruction about judgement asks listeners to consider the substance of the work they have seen.", "question": "How does Jesus answer the objection about making a man well on the Sabbath?"},
  {"id": 91183, "title": "The Offer to the Thirsty at the Feast", "subtitle": "Hearing before judging", "text": "John 7:25–53", "chapters": [[42, 7]], "start": 25, "end": 53, "kind": "story", "category": "John", "story": ["People in Jerusalem dispute where the Christ will come from. Officers are sent to seize Jesus. On the last day of the feast he calls the thirsty to come to him, speaking of what John connects with the Spirit. The officers return without him, struck by his words. Nicodemus asks whether the law judges someone before hearing him."], "lesson": "Nicodemus asks a modest but consequential question about fairness. The passage shows people reaching conclusions while others pause because they have listened.", "question": "What principle does Nicodemus appeal to when the leaders have already reached a judgement?"},
  {"id": 91184, "title": "The Accusers Leave One by One", "subtitle": "Mercy that calls for change", "text": "John 8:1–11", "chapters": [[42, 8]], "start": 1, "end": 11, "kind": "story", "category": "John", "story": ["In the account printed in the King James Version, scribes and Pharisees bring a woman accused of adultery and put a question to Jesus to test him. He writes on the ground and tells the one without sin to cast the first stone. The accusers leave one by one. Jesus speaks to the woman, declines to condemn her and tells her to leave her sin."], "lesson": "Jesus brings the accusers' own conduct into view and gives the woman a direct word about her future. The call to change is spoken after the threatening crowd has gone.", "question": "What happens to the accusers after Jesus answers, and what does he say once they have left?"},
  {"id": 91185, "title": "A Light and Two Witnesses", "subtitle": "Listening to the One sent by the Father", "text": "John 8:12–30", "chapters": [[42, 8]], "start": 12, "end": 30, "kind": "story", "category": "John", "story": ["Jesus calls himself the light of the world. When Pharisees challenge his testimony, he speaks of the Father who sent him. The discussion turns to where he is going and to the danger of refusing to believe who he is. He says they will understand after the Son of Man has been lifted up. Many believe as he speaks."], "lesson": "Jesus grounds his testimony in his relation to the Father. His hearers must attend to who is speaking before they can understand what it means to follow his light.", "question": "How does Jesus answer the objection that he is testifying about himself alone?"},
  {"id": 91186, "title": "The Claim to Be Abraham's Children", "subtitle": "Freedom that begins with truth", "text": "John 8:31–59", "chapters": [[42, 8]], "start": 31, "end": 59, "kind": "story", "category": "John", "story": ["Jesus tells people who have believed to continue in his word and says the truth will make them free. They appeal to Abraham as their ancestor. Jesus speaks of bondage to sin and asks why their actions do not resemble Abraham's. The exchange grows hostile. When Jesus speaks of his existence before Abraham, they take up stones, and he leaves the temple."], "lesson": "Jesus puts conduct and willingness to hear beside claims of ancestry. Freedom in this conversation involves receiving a truth the hearers find uncomfortable.", "question": "Why do the hearers object when Jesus speaks to them about becoming free?"},
  {"id": 91187, "title": "A Man Washes at Siloam", "subtitle": "Seeing a person before assigning blame", "text": "John 9:1–23", "chapters": [[42, 9]], "start": 1, "end": 23, "kind": "story", "category": "John", "story": ["Seeing a man blind from birth, the disciples ask whose sin caused it. Jesus redirects them towards God's works, makes clay and sends the man to wash. He returns seeing. Neighbours question his identity, and Pharisees dispute the Sabbath healing. His parents confirm that he is their son and was born blind, but fear the consequences of saying more."], "lesson": "The disciples begin with a question about blame. Jesus addresses the man himself and gives him something to do. The parents' caution shows what public testimony could cost.", "question": "What does the healed man know from experience that the others are disputing?"},
  {"id": 91188, "title": "The Man Cast Out and Found Again", "subtitle": "Truthful witness under pressure", "text": "John 9:24–41", "chapters": [[42, 9]], "start": 24, "end": 41, "kind": "story", "category": "John", "story": ["The leaders question the healed man again. He repeats that he was blind and now sees, then challenges their handling of the evidence. They cast him out. Jesus finds him and speaks to him about believing. The man believes and worships. Jesus closes the encounter with words about sight and the danger of claiming to see."], "lesson": "The man speaks from what he can honestly say, even when he is pressured to withdraw it. Jesus seeks him out after the leaders have rejected him.", "question": "What does Jesus do once he hears that the man has been cast out?"},
  {"id": 91189, "title": "The Shepherd Who Knows His Sheep", "subtitle": "Recognising a voice through care", "text": "John 10:1–21", "chapters": [[42, 10]], "start": 1, "end": 21, "kind": "story", "category": "John", "story": ["Jesus describes a shepherd calling his own sheep and leading them out. He speaks of himself as the door and the good shepherd who lays down his life. A hireling leaves when danger comes. Jesus also speaks of other sheep to bring into one flock. His words divide the hearers, and some recall that a demon could not open blind eyes."], "lesson": "The shepherd's authority is visible in his knowledge of the sheep and his willingness to bear danger for them. Jesus extends this care beyond the fold already in view.", "question": "What does the shepherd do when faced with the danger that makes the hireling leave?"},
  {"id": 91190, "title": "A Question on Solomon's Porch", "subtitle": "Trusting the Shepherd's hold", "text": "John 10:22–42", "chapters": [[42, 10]], "start": 22, "end": 42, "kind": "story", "category": "John", "story": ["At the feast of dedication people surround Jesus and ask him to say plainly whether he is the Christ. He points to his works and speaks of sheep who hear his voice and are held securely. After he speaks of his unity with the Father, people take up stones. Jesus answers from Scripture and points again to his works. He then goes across the Jordan, where many believe."], "lesson": "Jesus' promise of safety belongs to the relationship of hearing and following. Beyond Jordan people remember John's testimony and weigh it against what they now see.", "question": "What two actions does Jesus describe on the part of the sheep, and what does he promise them?"},
  {"id": 91191, "title": "The Message From Bethany", "subtitle": "Hope spoken to a grieving sister", "text": "John 11:1–27", "chapters": [[42, 11]], "start": 1, "end": 27, "kind": "story", "category": "John", "story": ["Mary and Martha send news that Lazarus is ill. Jesus waits before travelling, then tells the disciples that Lazarus has died. Martha meets him outside Bethany and speaks of what might have happened had he been there. Jesus speaks of resurrection and life. Martha confesses her belief that he is the Christ, the Son of God."], "lesson": "Martha speaks her disappointment openly and also listens to Jesus' promise. Her confession is made before she sees anything change at the tomb.", "question": "What does Martha believe about Jesus before Lazarus comes out of the tomb?"},
  {"id": 91192, "title": "Jesus Weeps and Lazarus Comes Out", "subtitle": "Compassion and life at the tomb", "text": "John 11:28–57", "chapters": [[42, 11]], "start": 28, "end": 57, "kind": "story", "category": "John", "story": ["Mary comes out and falls at Jesus' feet. Seeing her and others weep, Jesus is moved and weeps. At the tomb he asks for the stone to be removed, prays aloud and calls Lazarus out. Lazarus emerges wrapped in grave clothes, and Jesus asks the people to free him. Some believe; others report to the leaders, who begin planning Jesus' death."], "lesson": "Jesus' tears have their place beside his authority to call Lazarus. The leaders' reaction shows that evidence can become threatening when people fear what they will lose.", "question": "What two very different responses follow the raising of Lazarus?"},
  {"id": 91193, "title": "Perfume at Supper and Branches on the Road", "subtitle": "Honouring Jesus before the crowds change", "text": "John 12:1–19", "chapters": [[42, 12]], "start": 1, "end": 19, "kind": "story", "category": "John", "story": ["At a supper in Bethany, Martha serves, Lazarus sits at the table and Mary anoints Jesus' feet with costly ointment. Judas objects, and Jesus connects her act with his burial. Crowds come to see Lazarus, and the chief priests consider killing him too. When Jesus approaches Jerusalem, people greet him with palm branches, and he rides on a young donkey."], "lesson": "Mary's gift receives meaning from the approaching burial. The crowds see a public welcome, while John also records what leaders are planning in response to Lazarus.", "question": "What different motives for coming to Bethany or reacting to Lazarus does John describe?"},
  {"id": 91194, "title": "The Grain That Falls Into the Ground", "subtitle": "Fruit through surrender", "text": "John 12:20–50", "chapters": [[42, 12]], "start": 20, "end": 50, "kind": "story", "category": "John", "story": ["Some Greeks ask Philip to see Jesus. Their request reaches Jesus through Philip and Andrew. He says his hour has come and pictures a grain dying to bear much fruit. Troubled, he prays that the Father's name be glorified. A voice answers. He speaks of being lifted up and calls the people to believe in the light. John reflects on unbelief and on the fear that keeps some believers silent."], "lesson": "Jesus speaks about fruit when his own death draws near. John also names public approval as something that can restrain a person's confession.", "question": "Why is the picture of the grain appropriate when Jesus says his hour has arrived?"},
  {"id": 91195, "title": "The Towel and the Basin", "subtitle": "Serving from a secure place", "text": "John 13:1–20", "chapters": [[42, 13]], "start": 1, "end": 20, "kind": "story", "category": "John", "story": ["At supper Jesus sets aside his outer clothing, takes a towel and washes the disciples' feet. Peter objects, then asks for more than his feet to be washed. Jesus returns to the table and explains what he has done. Their Lord and Teacher has served them in a way they are to practise for one another."], "lesson": "Jesus knows where he comes from and where he is going when he kneels to serve. His example puts a concrete duty before people who call him Lord.", "question": "How does Jesus use the titles Teacher and Lord when he explains his action?"},
  {"id": 91196, "title": "Into the Night", "subtitle": "Love when loyalty is tested", "text": "John 13:21–38", "chapters": [[42, 13]], "start": 21, "end": 38, "kind": "story", "category": "John", "story": ["Jesus tells the disciples that one of them will betray him. After he gives Judas a morsel, Judas goes out into the night. Jesus speaks of his coming departure and gives a command to love one another as he has loved them. Peter says he will lay down his life for Jesus. Jesus tells him he will deny him three times."], "lesson": "Jesus gives the command to love in a room marked by betrayal and impending failure. The test of that love will come when loyalty costs more than the disciples expect.", "question": "What does Jesus say will identify his disciples to other people?"},
  {"id": 91197, "title": "A Place in the Father's House", "subtitle": "Trust when the road ahead is unclear", "text": "John 14:1–14", "chapters": [[42, 14]], "start": 1, "end": 14, "kind": "story", "category": "John", "story": ["Jesus tells the troubled disciples to believe and speaks of preparing a place for them. Thomas asks how they can know the way. Jesus identifies himself as the way, the truth and the life. Philip asks to see the Father. Jesus directs him to what they have seen and heard from him, and speaks of prayer in his name."], "lesson": "Thomas and Philip ask for different kinds of clarity. Jesus answers by drawing them back to the person with whom they have been living and learning.", "question": "How does Jesus answer Philip's request to see the Father?"},
  {"id": 91198, "title": "The Promise of the Comforter", "subtitle": "Peace and obedience in Jesus' absence", "text": "John 14:15–31", "chapters": [[42, 14]], "start": 15, "end": 31, "kind": "story", "category": "John", "story": ["Jesus connects love with keeping his commandments and promises another Comforter. He says his disciples will not be left as orphans. Judas, other than Iscariot, asks why Jesus will reveal himself to them. Jesus speaks of making a home with those who love him, of the Spirit teaching and reminding them, and of the peace he leaves them."], "lesson": "The Spirit's work includes bringing Jesus' words back to mind. His promise of peace sits beside the call to keep those words through what is coming.", "question": "What does Jesus say the Comforter will teach or bring to remembrance?"},
  {"id": 91199, "title": "The Vine and Its Branches", "subtitle": "Fruit that comes from abiding", "text": "John 15:1–17", "chapters": [[42, 15]], "start": 1, "end": 17, "kind": "story", "category": "John", "story": ["Jesus describes himself as the vine and his Father as the gardener. Branches bear fruit by remaining in the vine, and the gardener tends them. Jesus asks the disciples to remain in his love and to love one another. He calls them friends and speaks of choosing them to bear lasting fruit."], "lesson": "A branch receives what sustains its fruit before it produces anything. Jesus gives abiding a concrete setting through his words, obedience and love for others.", "question": "What actions does Jesus connect with remaining in his love?"},
  {"id": 91200, "title": "When the World Hates You", "subtitle": "Witness in the face of opposition", "text": "John 15:18–27", "chapters": [[42, 15]], "start": 18, "end": 27, "kind": "story", "category": "John", "story": ["Jesus warns that the world has hated him and will hate his followers. He recalls that a servant is not greater than his master. He explains how his words and works make rejection accountable. The Comforter will bear witness, and the disciples who have been with him from the beginning will also testify."], "lesson": "Opposition is something Jesus prepares his disciples for in advance. He joins their memory of what they have seen to the witness of the Spirit.", "question": "Why does Jesus say these disciples are able to bear witness about him?"},
  {"id": 91201, "title": "The Work of the Spirit of Truth", "subtitle": "Help after Jesus goes", "text": "John 16:1–15", "chapters": [[42, 16]], "start": 1, "end": 15, "kind": "story", "category": "John", "story": ["Jesus tells the disciples why he has warned them about exclusion and persecution. Their hearts are filled with sorrow at his departure. He says his going makes way for the Comforter, who will convict the world concerning sin, righteousness and judgement. The Spirit of truth will guide the disciples and glorify Jesus."], "lesson": "The disciples see the loss before them. Jesus also describes help they will receive, including guidance for things they cannot yet bear to hear.", "question": "What does Jesus say the Spirit will do for the disciples that they need after his departure?"},
  {"id": 91202, "title": "A Little While", "subtitle": "Joy after grief and peace in trouble", "text": "John 16:16–33", "chapters": [[42, 16]], "start": 16, "end": 33, "kind": "story", "category": "John", "story": ["The disciples puzzle over Jesus' words about seeing him after a little while. He compares their coming sorrow and joy to the anguish and relief of childbirth. He speaks of asking the Father, then warns that they will scatter and leave him. He tells them they will have trouble in the world and gives them ground for courage in his victory."], "lesson": "Jesus gives the disciples language for grief that will feel final while it lasts. He also names their coming failure before speaking peace to them.", "question": "What does Jesus say will happen to their sorrow, and what does he tell them about coming trouble?"},
  {"id": 91203, "title": "Jesus Prays for Those Given to Him", "subtitle": "Knowing the Father and being kept in his name", "text": "John 17:1–12", "chapters": [[42, 17]], "start": 1, "end": 12, "kind": "story", "category": "John", "story": ["Jesus lifts his eyes and prays about the hour before him. He speaks of eternal life as knowing the Father and the one he sent. He brings before the Father the people who have received his words. As he prepares to leave the world, he asks the Father to keep them in his name."], "lesson": "Jesus speaks of eternal life in terms of knowing God. The prayer gives the disciples' security a place in the Father's care as Jesus' departure approaches.", "question": "How does Jesus describe eternal life as he begins to pray?"},
  {"id": 91204, "title": "A Prayer for Those Who Will Believe", "subtitle": "Unity, truth and a shared witness", "text": "John 17:13–26", "chapters": [[42, 17]], "start": 13, "end": 26, "kind": "story", "category": "John", "story": ["Jesus prays for his disciples to be kept from evil while they remain in the world. He asks that they be sanctified through the truth and speaks of sending them as the Father sent him. Then he prays for people who will believe through their word, asking that they be one and that the world may know the Father sent him."], "lesson": "Jesus includes later hearers in his prayer. The unity he seeks belongs with truth and mission, because it bears witness to the Father who sent him.", "question": "How does Jesus connect the oneness of believers with what the world may come to know?"},
  {"id": 91205, "title": "The Garden, the Door and the Fire", "subtitle": "Jesus steps forward while Peter draws back", "text": "John 18:1–27", "chapters": [[42, 18]], "start": 1, "end": 27, "kind": "story", "category": "John", "story": ["Judas brings a company to a garden Jesus and the disciples know. Jesus goes forward to meet them and asks that his followers be let go. Peter strikes a servant, and Jesus tells him to put away his sword. Jesus is led first to Annas. Peter enters the courtyard and denies being a disciple. As Jesus answers questions about his teaching, Peter again denies knowing him."], "lesson": "Jesus acts to protect his followers and speaks openly when questioned. John's movement between Jesus and Peter shows two responses under pressure.", "question": "What does Jesus ask for the disciples at the arrest, and what does Peter say about belonging to him?"},
  {"id": 91206, "title": "Pilate Asks About Truth", "subtitle": "Listening when a claim challenges your authority", "text": "John 18:28–40", "chapters": [[42, 18]], "start": 28, "end": 40, "kind": "story", "category": "John", "story": ["Jesus is led to Pilate. The accusers stay outside the hall to avoid defilement before Passover. Inside, Pilate asks about kingship, and Jesus speaks of a kingdom whose servants would fight if it belonged to this world. He says he came to bear witness to the truth. Pilate asks what truth is, goes outside and offers a release. The people call for Barabbas."], "lesson": "Pilate asks a striking question and leaves before John records any answer from Jesus. The scene asks whether our questions leave room to hear what might demand a decision.", "question": "How does Jesus explain the character of his kingdom to Pilate?"},
  {"id": 91207, "title": "The Crown and the Appeal to Caesar", "subtitle": "Authority and accountability", "text": "John 19:1–16", "chapters": [[42, 19]], "start": 1, "end": 16, "kind": "story", "category": "John", "story": ["Pilate has Jesus scourged, and soldiers crown and dress him in mockery. Pilate brings him out, saying he finds no fault in him. Hearing that Jesus claimed to be God's Son, Pilate becomes more afraid. Jesus speaks of authority given from above. The appeal to Caesar increases the pressure on Pilate, and he gives Jesus over to be crucified."], "lesson": "Pilate's authority is real enough for his decision to matter. Jesus' words place that authority under a higher accountability.", "question": "What different pressures can you see in Pilate's actions and questions?"},
  {"id": 91208, "title": "The Written Charge and the Finished Work", "subtitle": "Care and faithfulness at the cross", "text": "John 19:17–30", "chapters": [[42, 19]], "start": 17, "end": 30, "kind": "story", "category": "John", "story": ["Jesus carries his cross to Golgotha, where he is crucified. Pilate's inscription names him King of the Jews. Soldiers divide his clothing, and women stand near the cross. Jesus entrusts his mother and the beloved disciple to each other's care. After receiving sour wine, he says his work is finished and gives up his spirit."], "lesson": "Jesus gives attention to his mother's future while in suffering himself. John records that personal act in the same scene as the public inscription and Jesus' last words.", "question": "What responsibility does Jesus give to the disciple standing near his mother?"},
  {"id": 91209, "title": "A Witness and a Burial Before Sunset", "subtitle": "Courage when public favour has gone", "text": "John 19:31–42", "chapters": [[42, 19]], "start": 31, "end": 42, "kind": "story", "category": "John", "story": ["Soldiers come to break the legs of the crucified men but find Jesus already dead. One pierces his side, and the witness insists on what he saw. Joseph of Arimathea, previously a secret disciple, asks for the body. Nicodemus brings spices. They prepare Jesus' body and lay it in a nearby tomb before the close of the preparation day."], "lesson": "Joseph and Nicodemus use their opportunity to care for Jesus after his death. Their actions bring a measure of public courage into lives John earlier describes as cautious.", "question": "How does Nicodemus's action here compare with the circumstances of his first visit in John 3?"},
  {"id": 91210, "title": "Mary Hears Her Name", "subtitle": "Recognition in the place of grief", "text": "John 20:1–18", "chapters": [[42, 20]], "start": 1, "end": 18, "kind": "story", "category": "John", "story": ["Mary Magdalene finds the stone removed and tells Peter and the beloved disciple. They see the linen cloths in the tomb. Mary stays outside weeping. She sees angels, then someone she takes to be the gardener. When Jesus calls her by name, she recognises him. He sends her to his brethren, and she tells them she has seen the Lord."], "lesson": "Mary comes looking for a body and leaves with a message from Jesus. His speaking her name marks the moment recognition comes.", "question": "What does Mary assume at first, and what changes her understanding?"},
  {"id": 91211, "title": "Closed Doors and Thomas's Confession", "subtitle": "Peace for fearful disciples and faith for readers", "text": "John 20:19–31", "chapters": [[42, 20]], "start": 19, "end": 31, "kind": "story", "category": "John", "story": ["Jesus comes among disciples gathered behind closed doors, speaks peace and shows his wounds. He sends them and speaks of the Holy Spirit. Thomas, absent that evening, wants to see the wounds for himself. Jesus returns and addresses him directly. Thomas calls him his Lord and God. John explains why these signs have been written down for readers."], "lesson": "Jesus takes Thomas's stated difficulty seriously and calls him to believe. John then turns towards readers who will encounter the signs through testimony.", "question": "How does John's stated purpose connect Thomas's encounter to your reading of the Gospel?"},
  {"id": 91212, "title": "Breakfast by the Lake", "subtitle": "Care after a night of empty nets", "text": "John 21:1–14", "chapters": [[42, 21]], "start": 1, "end": 14, "kind": "story", "category": "John", "story": ["Peter and several disciples fish through the night and catch nothing. A man on shore tells them where to cast the net. The catch is so large they cannot draw it into the boat. The beloved disciple recognises Jesus, and Peter goes through the water to him. On shore they find a fire and food, and Jesus invites them to breakfast."], "lesson": "The risen Jesus meets the disciples in familiar work and provides a meal. John gives time to this quiet welcome before recording what Jesus will ask of Peter.", "question": "What details show that Jesus had prepared for the disciples before they came ashore?"},
  {"id": 91213, "title": "Peter Is Asked to Feed the Sheep", "subtitle": "Love expressed through patient responsibility", "text": "John 21:15–25", "chapters": [[42, 21]], "start": 15, "end": 25, "kind": "story", "category": "John", "story": ["After breakfast Jesus asks Peter three times whether he loves him and gives him responsibility for his sheep. He speaks about what following will cost Peter. Seeing the beloved disciple, Peter asks about him. Jesus turns Peter back to his own call to follow. John corrects a rumour about the other disciple and closes with his testimony."], "lesson": "Jesus gives Peter a practical expression for his love: care for the people entrusted to him. When Peter asks about someone else's path, Jesus puts his own responsibility before him again.", "question": "What task follows each question about Peter's love?"}
];
